	struct Snapshot
	{
		X64State                 state {};
		std::array<uint8_t, 512> memory {};
		std::array<uint64_t, 4>  stack {};
	};

	alignas(32) std::array<uint8_t, 512> working_memory {};
	std::array<uint64_t, 4>              return_stack {};
	auto write_memory  = [](uint8_t* memory, size_t offset, const auto& value) { std::memcpy(memory + offset, &value, sizeof(value)); };
	auto set_xmm_float = [](X64State* state, uint8_t reg, float value) { std::memcpy(&state->xmm[reg][0], &value, sizeof(value)); };
	auto set_xmm_double = [](X64State* state, uint8_t reg, double value) { std::memcpy(&state->xmm[reg][0], &value, sizeof(value)); };
	auto set_xmm_float_lane = [](X64State* state, uint8_t reg, uint8_t lane, float value)
	{ std::memcpy(reinterpret_cast<uint8_t*>(state->xmm[reg]) + lane * sizeof(value), &value, sizeof(value)); };
	auto get_xmm_float = [](const X64State& state, uint8_t reg)
	{
		float value = 0.0F;
		std::memcpy(&value, &state.xmm[reg][0], sizeof(value));
		return value;
	};
	auto get_xmm_double = [](const X64State& state, uint8_t reg)
	{
		double value = 0.0;
		std::memcpy(&value, &state.xmm[reg][0], sizeof(value));
		return value;
	};
	auto get_xmm_float_lane = [](const X64State& state, uint8_t reg, uint8_t lane)
	{
		float value = 0.0F;
		std::memcpy(&value, reinterpret_cast<const uint8_t*>(state.xmm[reg]) + lane * sizeof(value), sizeof(value));
		return value;
	};
	auto execute = [&](const uint8_t* code, size_t code_size, bool fast, bool handle_host_calls, const auto& initialize, Snapshot* snapshot)
	{
		EnableFastBlocks(fast);
		const uint32_t iterations = fast ? 8 : 1;
		for (uint32_t iteration = 0; iteration < iterations; iteration++)
		{
			for (size_t i = 0; i < working_memory.size(); i++)
			{
				working_memory[i] = static_cast<uint8_t>(i * 37 + 11);
			}
			return_stack.fill(0);
			snapshot->state = {};
			for (uint8_t reg = 0; reg < 16; reg++)
			{
				snapshot->state.gpr[reg] = 0x0102030405060708ULL ^ (static_cast<uint64_t>(reg) << 52u);
				for (uint8_t lane = 0; lane < 4; lane++)
				{
					snapshot->state.xmm[reg][lane] = 0x8877665544332211ULL ^ (static_cast<uint64_t>(reg) << 48u) ^ lane;
				}
			}
			snapshot->state.rip    = reinterpret_cast<uint64_t>(code);
			snapshot->state.gpr[4] = reinterpret_cast<uint64_t>(return_stack.data());
			snapshot->state.rflags = 0x8d5;
			initialize(&snapshot->state, working_memory.data(), code);
			const auto result =
			    handle_host_calls ? X64Interpreter {FastHostCall}.Run(&snapshot->state, 128) : X64Interpreter {}.Run(&snapshot->state, 128);
			if (result != X64RunResult::Returned || snapshot->state.rip != 0) return false;
		}
		snapshot->memory = working_memory;
		snapshot->stack  = return_stack;
		return true;
	};
	auto equivalent = [](const Snapshot& slow, const Snapshot& fast)
	{
		return std::memcmp(slow.state.gpr, fast.state.gpr, sizeof(slow.state.gpr)) == 0 &&
		       std::memcmp(slow.state.xmm, fast.state.xmm, sizeof(slow.state.xmm)) == 0 && slow.state.rflags == fast.state.rflags &&
		       slow.memory == fast.memory && slow.stack == fast.stack;
	};
	auto verify = [&](const auto& code, const auto& initialize, const auto& expected)
	{
		Snapshot slow {};
		Snapshot fast {};
		if (!execute(code.data(), code.size(), false, false, initialize, &slow)) return false;
		X64SetFastBlockTestTarget(reinterpret_cast<uint64_t>(code.data()));
		return execute(code.data(), code.size(), true, false, initialize, &fast) &&
		       X64FastBlockTestTargetInstructionCount() != 0 && equivalent(slow, fast) && expected(fast);
	};
	auto verify_host_call = [&](const auto& code, const auto& initialize, const auto& expected)
	{
		Snapshot slow {};
		Snapshot fast {};
		if (!execute(code.data(), code.size(), false, true, initialize, &slow)) return false;
		X64SetFastBlockTestTarget(reinterpret_cast<uint64_t>(code.data()));
		return execute(code.data(), code.size(), true, true, initialize, &fast) &&
		       X64FastBlockTestTargetInstructionCount() != 0 && equivalent(slow, fast) && expected(fast);
	};

	constexpr uint64_t index             = 2;
	const bool         integer_memory_ok = verify(
        integer_memory_code,
        [&](X64State* state, uint8_t* memory, const uint8_t*)
        {
            constexpr uint32_t source  = 0x12345678;
            constexpr uint32_t addend  = 0x01020304;
            constexpr uint32_t initial = 0xff00ff00;
            write_memory(memory, 0x80 + index * 4, source);
            state->gpr[12] = reinterpret_cast<uint64_t>(memory);
            state->gpr[13] = index;
            state->gpr[14] = addend;
            state->gpr[15] = initial;
        },
        [&](const Snapshot& result)
        {
            constexpr uint32_t source   = 0x12345678;
            constexpr uint32_t addend   = 0x01020304;
            constexpr uint32_t initial  = 0xff00ff00;
            constexpr uint32_t expected = source + addend;
            uint32_t           stored   = 0;
            std::memcpy(&stored, result.memory.data() + 0x84 + index * 4, sizeof(stored));
            return stored == expected && static_cast<uint32_t>(result.state.gpr[0]) == source &&
                   static_cast<uint32_t>(result.state.gpr[15]) == (initial & expected & addend);
        });

