	    X64A64DynarecNativeOnlyAdmissionEnvironmentValueEnabledForTest(value) &&
	    X64A64DynarecAvailableForTest();
	const bool strict_expected =
	    value != nullptr && std::strcmp(value, "1") == 0 &&
	    X64A64DynarecAvailableForTest();
#else
	(void)value;
	const bool expected = false;
	const bool strict_expected = false;
#endif
	const bool requested = X64A64DynarecNativeOnlyAdmissionRequestedForTest();
	const bool strict_coverage =
	    X64A64DynarecNativeOnlyAdmissionStrictCoverageRequestedForTest();
