bool BenchmarkA64DynarecCompiledArchive()
{
	const char* archive_value = std::getenv(
	    "LUMEN_X64_A64_DYNAREC_COMPILED_ARCHIVE");
	const char* admission_value = std::getenv(
	    "LUMEN_X64_A64_DYNAREC_DELAYED_POSITIVE_ADMISSION");
	if (std::getenv("LUMEN_X64_A64_DYNAREC") != nullptr ||
	    archive_value == nullptr ||
	    (std::strcmp(archive_value, "0") != 0 &&
	     std::strcmp(archive_value, "1") != 0) ||
	    admission_value == nullptr || std::strcmp(admission_value, "1") != 0 ||
	    !X64A64DynarecAvailableForTest() ||
	    !X64A64DynarecDefaultRequestedForTest() ||
	    !X64A64DynarecSeparateNegativeCacheAvailableForTest())
	{
		return false;
	}
	const bool policy = std::strcmp(archive_value, "1") == 0;
	if (!A64AdmissionGateExpected() ||
	    A64CompiledArchiveGateExpected() != policy ||
	    X64A64DynarecCompiledArchiveRequestedForTest() != policy)
	{
		return false;
	}

	A64AdmissionEnvironment environment;
	X64ResetA64DynarecCacheForTest();
	A64DynarecCacheResetOnExit reset_on_exit;
	A64AdmissionFixture fixture;
	if (!fixture.Initialize()) return false;

	// Decode C outside both timed windows, discard its native entry, then
	// publish only A/B. This leaves the hot segment on two exact dispatch hits.
	if (!fixture.WarmNative(2)) return false;
	X64ResetA64DynarecCacheForTest();
	if (!fixture.WarmNative(0) || !fixture.WarmNative(1)) return false;
	const auto hot_before = X64GetA64DynarecCacheTestStats();
	if (!hot_before.healthy || !hot_before.separate_negative_cache ||
	    !hot_before.delayed_positive_admission ||
	    hot_before.compiled_archive_requested != policy ||
	    hot_before.compiled_archive_enabled != policy ||
	    hot_before.archive_resident != 0 ||
	    hot_before.archive_global_capacity != 0 ||
	    hot_before.archive_global_invalid != 0)
	{
		return false;
	}

	constexpr uint64_t hot_executions = 5000000;
	uint64_t hot_checksum = 0;
	const auto hot_start = std::chrono::steady_clock::now();
	for (uint64_t iteration = 0; iteration < hot_executions; iteration++)
	{
		const size_t index = static_cast<size_t>(iteration & 1u);
		const uint64_t payload = index + 1u;
		const auto snapshot = fixture.RunBlock(index, payload);
		if (snapshot.result != X64RunResult::Returned || snapshot.rip != 0 ||
		    snapshot.rax != payload)
		{
			return false;
		}
		hot_checksum += snapshot.rax;
	}
	const uint64_t hot_duration = static_cast<uint64_t>(
	    std::chrono::duration_cast<std::chrono::nanoseconds>(
	        std::chrono::steady_clock::now() - hot_start).count());
	const auto hot_after = X64GetA64DynarecCacheTestStats();
	A64CompiledArchiveCounterDelta hot_delta {};
	if (!A64CompiledArchiveCountersBetween(
	        hot_before, hot_after, &hot_delta) ||
	    hot_duration == 0 || hot_checksum != UINT64_C(7500000) ||
	    hot_delta.build_attempts != 0 || hot_delta.compile_attempts != 0 ||
	    hot_delta.positive_hits != hot_executions ||
	    hot_delta.negative_hits != 0 || hot_delta.evictions != 0 ||
	    hot_delta.positive_evictions != 0 ||
	    hot_delta.negative_evictions != 0 ||
	    hot_delta.admission_deferrals != 0 ||
	    hot_delta.admission_promotions != 0 ||
	    !A64CompiledArchiveCountersAreZero(hot_delta) ||
	    hot_after.archive_resident != hot_before.archive_resident ||
	    hot_after.archive_code_resident != hot_before.archive_code_resident ||
	    hot_after.archive_capacity_resident !=
	        hot_before.archive_capacity_resident ||
	    hot_after.archive_global_capacity !=
	        hot_before.archive_global_capacity ||
	    hot_after.archive_global_invalid != 0 ||
	    hot_after.compiled_archive_requested != policy ||
	    hot_after.compiled_archive_enabled != policy ||
	    !hot_after.healthy)
	{
		return false;
	}

	// Establish the frozen timed state. A/B are hits; C first defers and then
	// publishes, evicting A. With the candidate, A is now the only archive item.
	for (size_t iteration = 0; iteration < 6; iteration++)
	{
		const size_t index = iteration / 2u;
		if (!fixture.RunReturned(index, index + 1u)) return false;
	}
	const auto churn_before = X64GetA64DynarecCacheTestStats();
	if (!churn_before.healthy ||
	    churn_before.compiled_archive_requested != policy ||
	    churn_before.compiled_archive_enabled != policy ||
	    churn_before.archive_invalid != 0 ||
	    churn_before.archive_budget_drops != 0 ||
	    churn_before.archive_drops != 0 ||
	    churn_before.archive_global_peak > 16u * 1024u * 1024u ||
	    churn_before.archive_global_invalid != 0)
	{
		return false;
	}
	if (!policy)
	{
		if (churn_before.archive_probes != 0 ||
		    churn_before.archive_hits != 0 ||
		    churn_before.archive_misses != 0 ||
		    churn_before.archive_puts != 0 ||
		    churn_before.archive_stored != 0 ||
		    churn_before.archive_resident != 0 ||
		    churn_before.archive_code_resident != 0 ||
		    churn_before.archive_capacity_resident != 0 ||
		    churn_before.archive_global_capacity != 0)
		{
			return false;
		}
	} else if (churn_before.archive_resident != 1 ||
	           churn_before.archive_code_resident == 0 ||
	           churn_before.archive_capacity_resident == 0 ||
	           churn_before.archive_global_capacity !=
	               churn_before.archive_capacity_resident)
	{
		return false;
	}

	constexpr uint64_t churn_executions = 300000;
	uint64_t churn_checksum = 0;
	const auto churn_start = std::chrono::steady_clock::now();
	for (uint64_t iteration = 0; iteration < churn_executions; iteration++)
	{
		const size_t index = static_cast<size_t>((iteration / 2u) % 3u);
		const uint64_t payload = index + 1u;
		const auto snapshot = fixture.RunBlock(index, payload);
		if (snapshot.result != X64RunResult::Returned || snapshot.rip != 0 ||
		    snapshot.rax != payload)
		{
			return false;
		}
		churn_checksum += snapshot.rax;
	}
	const uint64_t churn_duration = static_cast<uint64_t>(
	    std::chrono::duration_cast<std::chrono::nanoseconds>(
	        std::chrono::steady_clock::now() - churn_start).count());
	const auto churn_after = X64GetA64DynarecCacheTestStats();
	A64CompiledArchiveCounterDelta churn_delta {};
	if (!A64CompiledArchiveCountersBetween(
	        churn_before, churn_after, &churn_delta) ||
	    churn_duration == 0 || churn_checksum != UINT64_C(600000) ||
	    churn_delta.build_attempts != churn_executions ||
	    churn_delta.positive_hits != 0 || churn_delta.negative_hits != 0 ||
	    churn_delta.evictions != UINT64_C(150000) ||
	    churn_delta.positive_evictions != UINT64_C(150000) ||
	    churn_delta.negative_evictions != 0 ||
	    churn_delta.admission_deferrals != UINT64_C(150000) ||
	    churn_delta.admission_promotions != UINT64_C(150000) ||
	    churn_after.compiled_archive_requested != policy ||
	    churn_after.compiled_archive_enabled != policy ||
	    churn_after.archive_global_peak > 16u * 1024u * 1024u ||
	    churn_after.archive_global_invalid != 0 ||
	    !churn_after.healthy)
	{
		return false;
	}
	if (!policy)
	{
		if (churn_delta.compile_attempts != UINT64_C(150000) ||
		    !A64CompiledArchiveCountersAreZero(churn_delta) ||
		    churn_after.archive_resident != 0 ||
		    churn_after.archive_code_resident != 0 ||
		    churn_after.archive_capacity_resident != 0 ||
		    churn_after.archive_global_capacity != 0)
		{
			return false;
		}
	} else if (churn_delta.compile_attempts != 0 ||
	           churn_delta.archive_probes != UINT64_C(150000) ||
	           churn_delta.archive_hits != UINT64_C(150000) ||
	           churn_delta.archive_misses != 0 ||
	           churn_delta.archive_puts != UINT64_C(150000) ||
	           churn_delta.archive_stored != UINT64_C(150000) ||
	           churn_delta.archive_drops != 0 ||
	           churn_delta.archive_budget_drops != 0 ||
	           churn_delta.archive_invalid != 0 ||
	           churn_before.archive_resident != 1 ||
	           churn_after.archive_resident != 1 ||
	           churn_delta.archive_code_stored !=
	               churn_delta.archive_code_hit ||
	           churn_delta.archive_code_drop != 0 ||
	           churn_before.archive_code_resident !=
	               churn_after.archive_code_resident ||
	           churn_delta.archive_capacity_stored !=
	               churn_delta.archive_capacity_hit ||
	           churn_delta.archive_capacity_drop != 0 ||
	           churn_before.archive_capacity_resident !=
	               churn_after.archive_capacity_resident ||
	           churn_before.archive_global_capacity !=
	               churn_after.archive_global_capacity)
	{
		return false;
	}

	PrintA64DynarecCompiledArchiveBenchmark(
	    "hot", policy, hot_duration, hot_executions, hot_checksum,
	    hot_delta, hot_before, hot_after);
	PrintA64DynarecCompiledArchiveBenchmark(
	    "churn", policy, churn_duration, churn_executions, churn_checksum,
	    churn_delta, churn_before, churn_after);
	std::fflush(stdout);
	return true;
}

bool TestA64DynarecCachePolicy()
{
	FastBlockTestConfiguration configuration;
	// This suite validates the two-way cache's exact LRU and compile counts.
	// Archive restoration is covered independently by
	// TestA64DynarecCompiledArchive and would intentionally change those counts.
	A64CompiledArchiveDisabledForTest archive_disabled;
	EnableFastBlocks(true);
	EnableFastBlockChaining(false);
	EnableA64Dynarec(true);
	X64ResetA64DynarecCacheForTest();
	if (!X64A64DynarecAvailableForTest())
	{
		EnableA64DynarecSeparateNegativeCache(true);
		alignas(64) static constexpr std::array<uint8_t, 2> no_jit_code = {0x90, 0xc3};
		bool runs_ok = true;
		for (uint8_t iteration = 0; iteration < 3; iteration++)
		{
			uint64_t return_address = 0;
			X64State state {};
			state.rip    = reinterpret_cast<uint64_t>(no_jit_code.data());
			state.gpr[4] = reinterpret_cast<uint64_t>(&return_address);
			runs_ok = runs_ok && X64Interpreter {}.Run(&state, 4) == X64RunResult::Returned && state.rip == 0;
		}
		const auto stats = X64GetA64DynarecCacheTestStats();
		const bool separate_available = X64A64DynarecSeparateNegativeCacheAvailableForTest();
		EnableA64DynarecSeparateNegativeCache(false);
		EnableA64Dynarec(false);
		return runs_ok && !separate_available && stats.healthy &&
		       stats.build_attempts == 0 && stats.compile_attempts == 0 &&
		       stats.positive_hits == 0 && stats.negative_hits == 0 && stats.evictions == 0;
	}

	auto fail = [](const char* stage)
	{
		const auto stats = X64GetA64DynarecCacheTestStats();
		std::fprintf(stderr,
		             "A64DynarecCachePolicy failed at %s: build=%llu compile=%llu positive=%llu negative=%llu eviction=%llu healthy=%u\n",
		             stage, static_cast<unsigned long long>(stats.build_attempts),
		             static_cast<unsigned long long>(stats.compile_attempts),
		             static_cast<unsigned long long>(stats.positive_hits),
		             static_cast<unsigned long long>(stats.negative_hits),
		             static_cast<unsigned long long>(stats.evictions), stats.healthy ? 1u : 0u);
		return false;
	};

	constexpr size_t policy_cache_sets = 64;
	constexpr size_t policy_storage_size = 256u * 1024u;
	alignas(4096) static std::array<uint8_t, policy_storage_size> code_storage {};
	code_storage.fill(0xcc);
	auto fast_cache_set = [](uint64_t rip)
	{
		uint64_t key = rip >> 1u;
		key ^= key >> 11u;
		key ^= key >> 22u;
		return static_cast<size_t>(key) & (4096u - 1u);
	};
	std::array<std::array<size_t, 10>, policy_cache_sets> candidates {};
	std::array<std::array<size_t, 10>, policy_cache_sets> candidate_fast_sets {};
	std::array<uint8_t, policy_cache_sets> candidate_counts {};
	size_t selected_set = policy_cache_sets;
	for (size_t offset = 128; offset + 64 < policy_storage_size / 2; offset += 64)
	{
		const uint64_t rip = reinterpret_cast<uint64_t>(code_storage.data() + offset);
		if ((rip & 4095u) > 4096u - 64u) continue;
		const size_t set = X64A64DynarecCacheSetForTest(rip);
		if (set >= policy_cache_sets) return fail("set-index-range");
		const size_t fast_set = fast_cache_set(rip);
		auto& count = candidate_counts[set];
		bool duplicate_fast_set = false;
		for (uint8_t index = 0; index < count; index++)
		{
			duplicate_fast_set = duplicate_fast_set || candidate_fast_sets[set][index] == fast_set;
		}
		if (duplicate_fast_set) continue;
		candidates[set][count] = offset;
		candidate_fast_sets[set][count] = fast_set;
		count++;
		if (count == candidates[set].size())
		{
			selected_set = set;
			break;
		}
	}
	if (selected_set == policy_cache_sets) return fail("same-set-candidates");

	uint8_t* block_a = code_storage.data() + candidates[selected_set][0];
	uint8_t* block_b = code_storage.data() + candidates[selected_set][1];
	uint8_t* block_c = code_storage.data() + candidates[selected_set][2];
	uint8_t* active_block = code_storage.data() + candidates[selected_set][3];
	uint8_t* separate_positive_a = code_storage.data() + candidates[selected_set][4];
	uint8_t* separate_positive_b = code_storage.data() + candidates[selected_set][5];
	uint8_t* separate_positive_c = code_storage.data() + candidates[selected_set][6];
	uint8_t* separate_negative_a = code_storage.data() + candidates[selected_set][7];
	uint8_t* separate_negative_b = code_storage.data() + candidates[selected_set][8];
	uint8_t* separate_negative_c = code_storage.data() + candidates[selected_set][9];
	constexpr std::array<uint8_t, 4> load_return = {
	    0x48, 0x8b, 0x07, // MOV rax, [rdi]
	    0xc3,             // RET
	};
	for (auto* block: {block_a, block_b, block_c, separate_positive_a,
	                   separate_positive_b, separate_positive_c})
	{
		std::memcpy(block, load_return.data(), load_return.size());
		if (X64A64DynarecCacheSetForTest(reinterpret_cast<uint64_t>(block)) != selected_set)
		{
			return fail("same-set-identity");
		}
	}
	constexpr std::array<uint8_t, 6> call_return = {
	    0xe8, 0x00, 0x00, 0x00, 0x00, // CALL next
	    0xc3,                         // RET (host callback returns guest to zero)
	};
	std::memcpy(active_block, call_return.data(), call_return.size());

	struct PolicyMemory
	{
		uint64_t source = 0;
		std::array<uint64_t, 32> stack {};
	} memory;
	struct PolicyRun
	{
		X64RunResult result = X64RunResult::UnsupportedInstruction;
		uint64_t rax = 0;
		uint64_t rip = 0;
	};
	auto run_code = [&](uint8_t* entry, uint64_t initial_rax, uint64_t source,
	                    X64Interpreter::HostCall host_call = nullptr, size_t stack_index = 0)
	{
		memory.source = source;
		memory.stack.fill(0);
		X64State state {};
		state.rip    = reinterpret_cast<uint64_t>(entry);
		state.gpr[0] = initial_rax;
		state.gpr[7] = reinterpret_cast<uint64_t>(&memory.source);
		state.gpr[4] = reinterpret_cast<uint64_t>(&memory.stack[stack_index]);
		state.rflags = 0x202;
		g_test_regions = {{
		    {reinterpret_cast<uint64_t>(code_storage.data()),
		     reinterpret_cast<uint64_t>(code_storage.data() + code_storage.size()), true, false},
		    {reinterpret_cast<uint64_t>(&memory), reinterpret_cast<uint64_t>(&memory + 1), true, true},
		    {},
		}};
		PolicyRun snapshot {};
		snapshot.result = X64Interpreter(host_call, TranslateTestRegionAddress).Run(&state, 16);
		snapshot.rax = state.gpr[0];
		snapshot.rip = state.rip;
		g_test_regions = {};
		return snapshot;
	};
	auto run_load = [&](uint8_t* entry, uint64_t source)
	{
		return run_code(entry, 0, source);
	};
	auto returned_value = [&](uint8_t* entry, uint64_t value)
	{
		const auto result = run_load(entry, value);
		return result.result == X64RunResult::Returned && result.rip == 0 && result.rax == value;
	};
	auto compile_returned_value = [&](uint8_t* entry, uint64_t value)
	{
		return RunUntilA64DynarecCompileForTest([&]
		{
			return returned_value(entry, value);
		});
	};

	// The macOS candidate keeps positive executable entries and negative
	// identities in independent two-way sets. Exercise the unchanged shared
	// profile first, then prove independent MRU/victims, exact mutation keys,
	// quiescent profile barriers and fail-closed switching under re-entry.
	constexpr uint64_t or_negative_input = UINT64_C(0xaaaaaaaaaaaaaaa0);
	constexpr uint64_t or_negative_value = or_negative_input;
	if (X64A64DynarecSeparateNegativeCacheAvailableForTest())
	{
		constexpr std::array<uint8_t, 6> separate_negative_bytes = {
		    0xc5, 0xfc, 0x10, 0xc0, // VMOVUPS ymm0, ymm0 (unsupported width variant)
		    0x90, 0xc3,             // NOP; RET
		};
		for (auto* negative: {separate_negative_a, separate_negative_b,
		                      separate_negative_c})
		{
			std::memcpy(negative, separate_negative_bytes.data(),
			            separate_negative_bytes.size());
			if (X64A64DynarecCacheSetForTest(reinterpret_cast<uint64_t>(negative)) !=
			    selected_set)
			{
				return fail("separate-negative-set");
			}
		}

		EnableA64DynarecSeparateNegativeCache(false);
		X64ResetA64DynarecCacheForTest();
		if (!compile_returned_value(separate_positive_a, 0x1111111111111111ULL) ||
		    !compile_returned_value(separate_positive_b, 0x2222222222222222ULL) ||
		    !returned_value(separate_positive_a, 0xaaaaaaaaaaaaaaaaULL))
		{
			return fail("shared-mixed-warm");
		}
		for (uint8_t attempt = 0; attempt < 4; attempt++)
		{
			const auto negative = run_code(separate_negative_a, or_negative_input, 0);
			if (negative.result != X64RunResult::Returned || negative.rip != 0 ||
			    negative.rax != or_negative_value)
			{
				return fail("shared-negative-run");
			}
		}
		auto candidate_stats = X64GetA64DynarecCacheTestStats();
		if (!A64DynarecLegacyBuildCountMatches(candidate_stats, 3) ||
		    candidate_stats.compile_attempts != 2 ||
		    candidate_stats.positive_hits != 1 || candidate_stats.negative_hits != 2 ||
		    candidate_stats.evictions != 1 || candidate_stats.positive_evictions != 1 ||
		    candidate_stats.negative_evictions != 0 || candidate_stats.separate_negative_cache ||
		    !A64DynarecCompletedAdmissionsMatch(candidate_stats, 2) ||
		    !candidate_stats.healthy)
		{
			return fail("shared-mixed-legacy");
		}
		if (!returned_value(separate_positive_a, 0xaaaaaaaaaaaaaaaaULL) ||
		    !compile_returned_value(separate_positive_b, 0xbbbbbbbbbbbbbbbbULL))
		{
			return fail("shared-mixed-victim");
		}
		candidate_stats = X64GetA64DynarecCacheTestStats();
		if (!A64DynarecLegacyBuildCountMatches(candidate_stats, 4) ||
		    candidate_stats.compile_attempts != 3 ||
		    candidate_stats.positive_hits != 2 || candidate_stats.evictions != 2 ||
		    candidate_stats.positive_evictions != 1 ||
		    candidate_stats.negative_evictions != 1 ||
		    !A64DynarecCompletedAdmissionsMatch(candidate_stats, 3) ||
		    !candidate_stats.healthy)
		{
			return fail("shared-mixed-rebuild");
		}

		EnableA64DynarecSeparateNegativeCache(true);
		X64ResetA64DynarecCacheForTest();
		if (!compile_returned_value(separate_positive_a, 0x1111111111111111ULL) ||
		    !compile_returned_value(separate_positive_b, 0x2222222222222222ULL))
		{
			return fail("separate-positive-fill");
		}
		for (uint8_t attempt = 0; attempt < 3; attempt++)
		{
			const auto negative = run_code(separate_negative_a, or_negative_input, 0);
			if (negative.result != X64RunResult::Returned || negative.rip != 0 ||
			    negative.rax != or_negative_value)
			{
				return fail("separate-negative-a");
			}
		}
		for (uint8_t attempt = 0; attempt < 4; attempt++)
		{
			const auto negative = run_code(separate_negative_b, or_negative_input, 0);
			if (negative.result != X64RunResult::Returned || negative.rip != 0 ||
			    negative.rax != or_negative_value)
			{
				return fail("separate-negative-b");
			}
		}
		candidate_stats = X64GetA64DynarecCacheTestStats();
		if (!A64DynarecLegacyBuildCountMatches(candidate_stats, 4) ||
		    candidate_stats.compile_attempts != 2 ||
		    candidate_stats.positive_hits != 0 || candidate_stats.negative_hits != 4 ||
		    candidate_stats.evictions != 0 || !candidate_stats.separate_negative_cache ||
		    !A64DynarecCompletedAdmissionsMatch(candidate_stats, 2) ||
		    !candidate_stats.healthy)
		{
			return fail("separate-independent-fill");
		}
		if (run_code(separate_negative_a, or_negative_input, 0).rax != or_negative_value)
			return fail("separate-negative-touch");
		for (uint8_t attempt = 0; attempt < 4; attempt++)
		{
			if (run_code(separate_negative_c, or_negative_input, 0).rax != or_negative_value)
				return fail("separate-negative-c");
		}
		if (!returned_value(separate_positive_a, 0xaaaaaaaaaaaaaaaaULL) ||
		    !returned_value(separate_positive_b, 0xbbbbbbbbbbbbbbbbULL) ||
		    run_code(separate_negative_a, or_negative_input, 0).rax != or_negative_value ||
		    run_code(separate_negative_b, or_negative_input, 0).rax != or_negative_value)
		{
			return fail("separate-independent-probe");
		}
		if (!returned_value(separate_positive_a, 0xaaaaaaaaaaaaaaaaULL) ||
		    !compile_returned_value(separate_positive_c, 0xccccccccccccccccULL) ||
		    !returned_value(separate_positive_a, 0xaaaaaaaaaaaaaaaaULL) ||
		    !compile_returned_value(separate_positive_b, 0xbbbbbbbbbbbbbbbbULL))
		{
			return fail("separate-positive-mru");
		}
		candidate_stats = X64GetA64DynarecCacheTestStats();
		if (!A64DynarecLegacyBuildCountMatches(candidate_stats, 8) ||
		    candidate_stats.compile_attempts != 4 ||
		    candidate_stats.positive_hits != 4 || candidate_stats.negative_hits != 8 ||
		    candidate_stats.evictions != 4 || candidate_stats.positive_evictions != 2 ||
		    candidate_stats.negative_evictions != 2 ||
		    !candidate_stats.separate_negative_cache ||
		    !A64DynarecCompletedAdmissionsMatch(candidate_stats, 4) ||
		    !candidate_stats.healthy)
		{
			return fail("separate-independent-mru");
		}

		// A negative identity survives a same-RIP mutation in its own bank. The
		// positive mutation compiles without evicting it; reverting must hit the
		// exact old signature rather than rebuild or key only on RIP.
		X64ResetA64DynarecCacheForTest();
		if (run_code(separate_negative_a, or_negative_input, 0).rax != or_negative_value ||
		    run_code(separate_negative_a, or_negative_input, 0).rax != or_negative_value)
		{
			return fail("separate-mutation-negative");
		}
		const auto negative_mutation_stats =
		    X64GetA64DynarecCacheTestStats();
		separate_negative_a[0] = 0x90;
		separate_negative_a[1] = 0x90;
		separate_negative_a[2] = 0x90;
		separate_negative_a[3] = 0x90;
		const bool positive_mutation_compiled =
		    RunUntilA64DynarecCompileForTest([&]
		    {
			    const auto mutation =
			        run_code(separate_negative_a, 0x5555555555555555ULL, 0);
			    return mutation.result == X64RunResult::Returned && mutation.rip == 0 &&
			           mutation.rax == 0x5555555555555555ULL;
		    });
		const auto positive_mutation_stats =
		    X64GetA64DynarecCacheTestStats();
		std::memcpy(separate_negative_a, separate_negative_bytes.data(),
		            separate_negative_bytes.size());
		bool negative_reversion_hit = false;
		for (uint8_t attempt = 0; attempt < 4; attempt++)
		{
			if (run_code(separate_negative_a, or_negative_input, 0).rax != or_negative_value)
				return fail("separate-mutation-revert-run");
			if (X64GetA64DynarecCacheTestStats().negative_hits >
			    positive_mutation_stats.negative_hits)
			{
				negative_reversion_hit = true;
				break;
			}
		}
		candidate_stats = X64GetA64DynarecCacheTestStats();
		const uint64_t mutation_deferrals =
		    positive_mutation_stats.admission_deferrals -
		    negative_mutation_stats.admission_deferrals;
		const uint64_t mutation_promotions =
		    positive_mutation_stats.admission_promotions -
		    negative_mutation_stats.admission_promotions;
		const uint64_t mutation_builds =
		    positive_mutation_stats.build_attempts -
		    negative_mutation_stats.build_attempts;
		const uint64_t expected_mutation_admissions =
		    positive_mutation_stats.delayed_positive_admission ? 1u : 0u;
		if (!positive_mutation_compiled || !negative_reversion_hit ||
		    mutation_builds < mutation_deferrals ||
		    mutation_builds - mutation_deferrals != 1 ||
		    positive_mutation_stats.compile_attempts !=
		        negative_mutation_stats.compile_attempts + 1 ||
		    positive_mutation_stats.evictions != negative_mutation_stats.evictions ||
		    mutation_deferrals < expected_mutation_admissions ||
		    (!positive_mutation_stats.delayed_positive_admission &&
		     mutation_deferrals != 0) ||
		    mutation_promotions != expected_mutation_admissions ||
		    candidate_stats.evictions != positive_mutation_stats.evictions ||
		    candidate_stats.negative_hits <= positive_mutation_stats.negative_hits ||
		    !candidate_stats.healthy)
		{
			std::fprintf(
			    stderr,
			    "A64 mutation phases: negative=%llu/%llu/%llu/%llu/%llu/%llu "
			    "positive=%llu/%llu/%llu/%llu/%llu/%llu "
			    "reverted=%llu/%llu/%llu/%llu/%llu/%llu\n",
			    static_cast<unsigned long long>(negative_mutation_stats.build_attempts),
			    static_cast<unsigned long long>(negative_mutation_stats.compile_attempts),
			    static_cast<unsigned long long>(negative_mutation_stats.positive_hits),
			    static_cast<unsigned long long>(negative_mutation_stats.negative_hits),
			    static_cast<unsigned long long>(negative_mutation_stats.admission_deferrals),
			    static_cast<unsigned long long>(negative_mutation_stats.admission_promotions),
			    static_cast<unsigned long long>(positive_mutation_stats.build_attempts),
			    static_cast<unsigned long long>(positive_mutation_stats.compile_attempts),
			    static_cast<unsigned long long>(positive_mutation_stats.positive_hits),
			    static_cast<unsigned long long>(positive_mutation_stats.negative_hits),
			    static_cast<unsigned long long>(positive_mutation_stats.admission_deferrals),
			    static_cast<unsigned long long>(positive_mutation_stats.admission_promotions),
			    static_cast<unsigned long long>(candidate_stats.build_attempts),
			    static_cast<unsigned long long>(candidate_stats.compile_attempts),
			    static_cast<unsigned long long>(candidate_stats.positive_hits),
			    static_cast<unsigned long long>(candidate_stats.negative_hits),
			    static_cast<unsigned long long>(candidate_stats.admission_deferrals),
			    static_cast<unsigned long long>(candidate_stats.admission_promotions));
			return fail("separate-mutation-exact-key");
		}

		// A quiescent profile change destroys the old generation. No positive or
		// negative hit may cross either direction of the barrier.
		EnableA64DynarecSeparateNegativeCache(false);
		if (!returned_value(separate_positive_a, 0x1111111111111111ULL))
			return fail("separate-profile-shared-run");
		candidate_stats = X64GetA64DynarecCacheTestStats();
		if (candidate_stats.compile_attempts == 0)
		{
			if (!returned_value(separate_positive_a, 0x1111111111111111ULL))
				return fail("separate-profile-shared-run");
			candidate_stats = X64GetA64DynarecCacheTestStats();
		}
		if (!A64DynarecLegacyBuildCountMatches(candidate_stats, 1) ||
		    candidate_stats.compile_attempts != 1 ||
		    candidate_stats.positive_hits != 0 || candidate_stats.negative_hits != 0 ||
		    candidate_stats.evictions != 0 || candidate_stats.separate_negative_cache ||
		    !A64DynarecCompletedAdmissionsMatch(candidate_stats, 1) ||
		    !candidate_stats.healthy)
		{
			return fail("separate-profile-shared-reset");
		}
		EnableA64DynarecSeparateNegativeCache(true);
		if (!returned_value(separate_positive_a, 0x2222222222222222ULL))
			return fail("separate-profile-candidate-run");
		candidate_stats = X64GetA64DynarecCacheTestStats();
		if (candidate_stats.compile_attempts == 0)
		{
			if (!returned_value(separate_positive_a, 0x2222222222222222ULL))
				return fail("separate-profile-candidate-run");
			candidate_stats = X64GetA64DynarecCacheTestStats();
		}
		if (!A64DynarecLegacyBuildCountMatches(candidate_stats, 1) ||
		    candidate_stats.compile_attempts != 1 ||
		    candidate_stats.positive_hits != 0 || candidate_stats.negative_hits != 0 ||
		    candidate_stats.evictions != 0 || !candidate_stats.separate_negative_cache ||
		    !A64DynarecCompletedAdmissionsMatch(candidate_stats, 1) ||
		    !candidate_stats.healthy)
		{
			return fail("separate-profile-candidate-reset");
		}

		// A nested Run requesting another profile while the outer native CALL
		// entry is active must latch the tier instead of reclaiming its cache.
		uint8_t* separate_active = code_storage.data() + policy_storage_size / 2 + 128;
		std::memcpy(separate_active, call_return.data(), call_return.size());
		X64ResetA64DynarecCacheForTest();
		g_a64_cache_nested_count = 0;
		g_a64_cache_nested_profile = -1;
		if (!RunUntilA64DynarecCompileForTest([&]
		    {
			    return run_code(separate_active, 0, 0, A64CachePolicyHostCall, 24).result ==
			           X64RunResult::Returned;
		    }))
		{
			return fail("separate-active-warm");
		}
		g_a64_cache_nested_rips[0] = reinterpret_cast<uint64_t>(separate_positive_a);
		g_a64_cache_nested_rsps[0] = reinterpret_cast<uint64_t>(&memory.stack[4]);
		g_a64_cache_nested_source = reinterpret_cast<uint64_t>(&memory.source);
		g_a64_cache_nested_count = 1;
		g_a64_cache_nested_profile = 0;
		const auto active_profile_switch =
		    run_code(separate_active, 0, 0x3333333333333333ULL,
		             A64CachePolicyHostCall, 24);
		g_a64_cache_nested_count = 0;
		g_a64_cache_nested_profile = -1;
		EnableA64DynarecSeparateNegativeCache(true);
		if (active_profile_switch.result != X64RunResult::Returned ||
		    active_profile_switch.rip != 0 ||
		    g_a64_cache_nested_results[0] != X64RunResult::Returned ||
		    g_a64_cache_nested_values[0] != 0x3333333333333333ULL ||
		    X64GetA64DynarecCacheTestStats().healthy)
		{
			return fail("separate-active-profile-latch");
		}
		const auto active_latched_stats = X64GetA64DynarecCacheTestStats();
		if (!returned_value(separate_positive_a, 0x4444444444444444ULL))
			return fail("separate-active-latched-fallback");
		candidate_stats = X64GetA64DynarecCacheTestStats();
		if (candidate_stats.healthy ||
		    candidate_stats.build_attempts != active_latched_stats.build_attempts ||
		    candidate_stats.compile_attempts != active_latched_stats.compile_attempts ||
		    candidate_stats.positive_hits != active_latched_stats.positive_hits)
		{
			return fail("separate-active-latch-sticky");
		}
		X64ResetA64DynarecCacheForTest();
		EnableA64DynarecSeparateNegativeCache(false);
	}

	// Two independent blocks must remain resident and turn into exact positive
	// hits after one FastBlock observation plus one dynarec compilation each.
	X64ResetA64DynarecCacheForTest();
	if (!compile_returned_value(block_a, 0x1111111111111111ULL) ||
	    !compile_returned_value(block_b, 0x2222222222222222ULL))
	{
		return fail("ab-warm");
	}
	auto stats = X64GetA64DynarecCacheTestStats();
	if (!A64DynarecLegacyBuildCountMatches(stats, 2) || stats.compile_attempts != 2 ||
	    stats.positive_hits != 0 || stats.negative_hits != 0 || stats.evictions != 0 ||
	    !A64DynarecCompletedAdmissionsMatch(stats, 2) || !stats.healthy)
	{
		return fail("ab-resident");
	}
	if (!returned_value(block_a, 0xaaaaaaaaaaaaaaaaULL) ||
	    !returned_value(block_b, 0xbbbbbbbbbbbbbbbbULL))
	{
		return fail("ab-hit-run");
	}
	stats = X64GetA64DynarecCacheTestStats();
	if (!A64DynarecLegacyBuildCountMatches(stats, 2) || stats.compile_attempts != 2 ||
	    stats.positive_hits != 2 || stats.evictions != 0 ||
	    !A64DynarecCompletedAdmissionsMatch(stats, 2) || !stats.healthy)
	{
		return fail("ab-hit-count");
	}

	// Touch A after B, then insert C in the same set: B is the deterministic
	// victim. A remains a hit and the next B access must rebuild it.
	if (!returned_value(block_a, 0xaaaaaaaaaaaaaaaaULL) ||
	    !compile_returned_value(block_c, 0xccccccccccccccccULL))
	{
		return fail("abc-insert");
	}
	stats = X64GetA64DynarecCacheTestStats();
	if (!A64DynarecLegacyBuildCountMatches(stats, 3) || stats.compile_attempts != 3 ||
	    stats.positive_hits != 3 || stats.evictions != 1 ||
	    !A64DynarecCompletedAdmissionsMatch(stats, 3) || !stats.healthy)
	{
		return fail("abc-lru");
	}
	if (!returned_value(block_a, 0xaaaaaaaaaaaaaaaaULL) ||
	    !compile_returned_value(block_b, 0xbbbbbbbbbbbbbbbbULL))
	{
		return fail("abc-victim-probe");
	}
	stats = X64GetA64DynarecCacheTestStats();
	if (!A64DynarecLegacyBuildCountMatches(stats, 4) || stats.compile_attempts != 4 ||
	    stats.positive_hits != 4 || stats.evictions != 2 ||
	    !A64DynarecCompletedAdmissionsMatch(stats, 4) || !stats.healthy)
	{
		return fail("abc-victim-count");
	}

	// Keep active_block live across the host callback. Nested C evicts B; the
	// following nested B insertion must skip the still-active outer way and
	// reclaim C. A later outer hit proves the live entry was never destroyed.
	X64ResetA64DynarecCacheForTest();
	g_a64_cache_nested_count = 0;
	if (!RunUntilA64DynarecCompileForTest([&]
	    {
		    return run_code(active_block, 0, 0, A64CachePolicyHostCall, 24).result ==
		           X64RunResult::Returned;
	    }) ||
	    !compile_returned_value(block_b, 0x3333333333333333ULL))
	{
		return fail("active-warm");
	}
	const auto active_before = X64GetA64DynarecCacheTestStats();
	const bool delayed_admission = active_before.delayed_positive_admission;
	if (delayed_admission)
	{
		g_a64_cache_nested_rips = {
		    reinterpret_cast<uint64_t>(block_c),
		    reinterpret_cast<uint64_t>(block_c),
		    reinterpret_cast<uint64_t>(block_b),
		    reinterpret_cast<uint64_t>(block_b),
		};
		g_a64_cache_nested_rsps = {
		    reinterpret_cast<uint64_t>(&memory.stack[4]),
		    reinterpret_cast<uint64_t>(&memory.stack[8]),
		    reinterpret_cast<uint64_t>(&memory.stack[12]),
		    reinterpret_cast<uint64_t>(&memory.stack[16]),
		};
	} else
	{
		g_a64_cache_nested_rips = {
		    reinterpret_cast<uint64_t>(block_c),
		    reinterpret_cast<uint64_t>(block_b),
		};
		g_a64_cache_nested_rsps = {
		    reinterpret_cast<uint64_t>(&memory.stack[4]),
		    reinterpret_cast<uint64_t>(&memory.stack[12]),
		};
	}
	g_a64_cache_nested_source = reinterpret_cast<uint64_t>(&memory.source);
	g_a64_cache_nested_count = delayed_admission ? 4 : 2;
	const auto active_run = run_code(active_block, 0, 0x4444444444444444ULL,
	                                 A64CachePolicyHostCall, 24);
	const size_t nested_count = g_a64_cache_nested_count;
	g_a64_cache_nested_count = 0;
	if (active_run.result != X64RunResult::Returned || active_run.rip != 0)
	{
		return fail("active-nested-run");
	}
	for (size_t index = 0; index < nested_count; index++)
	{
		if (g_a64_cache_nested_results[index] != X64RunResult::Returned ||
		    g_a64_cache_nested_values[index] != 0x4444444444444444ULL)
		{
			return fail("active-nested-run");
		}
	}
	stats = X64GetA64DynarecCacheTestStats();
	const uint64_t nested_deferrals = stats.admission_deferrals -
	                                  active_before.admission_deferrals;
	const uint64_t nested_promotions = stats.admission_promotions -
	                                   active_before.admission_promotions;
	if (stats.build_attempts < active_before.build_attempts + nested_deferrals ||
	    stats.build_attempts - active_before.build_attempts - nested_deferrals != 2 ||
	    stats.compile_attempts != active_before.compile_attempts + 2 ||
	    stats.positive_hits != active_before.positive_hits + 1 ||
	    stats.evictions != active_before.evictions + 2 ||
	    nested_deferrals != (delayed_admission ? 2u : 0u) ||
	    nested_promotions != (delayed_admission ? 2u : 0u) || !stats.healthy)
	{
		return fail("active-nested-count");
	}
	const auto survivor_before = stats;
	if (run_code(active_block, 0, 0, A64CachePolicyHostCall, 24).result != X64RunResult::Returned)
	{
		return fail("active-survivor-run");
	}
	stats = X64GetA64DynarecCacheTestStats();
	if (stats.build_attempts != survivor_before.build_attempts ||
	    stats.compile_attempts != survivor_before.compile_attempts ||
	    stats.positive_hits != survivor_before.positive_hits + 1 ||
	    stats.evictions != survivor_before.evictions ||
	    stats.admission_deferrals != survivor_before.admission_deferrals ||
	    stats.admission_promotions != survivor_before.admission_promotions || !stats.healthy)
	{
		return fail("active-survivor-hit");
	}

	// A 256-bit VMOVUPS remains a valid FastBlock operand variant outside the
	// current 128-bit A64 move contract. Its exact signature gets one negative
	// entry; changing it to four NOPs produces a healthy positive entry.
	uint8_t* negative_block = code_storage.data() + policy_storage_size - 8192 + 128;
	constexpr std::array<uint8_t, 6> negative_bytes = {
	    0xc5, 0xfc, 0x10, 0xc0, // VMOVUPS ymm0, ymm0 (unsupported width variant)
	    0x90, 0xc3,             // NOP; RET
	};
	std::memcpy(negative_block, negative_bytes.data(), negative_bytes.size());
	X64ResetA64DynarecCacheForTest();
	for (uint8_t attempt = 0; attempt < 4; attempt++)
	{
		const auto negative = run_code(negative_block, or_negative_input, 0);
		if (negative.result != X64RunResult::Returned || negative.rip != 0 ||
		    negative.rax != or_negative_value)
		{
			return fail("negative-run");
		}
	}
	stats = X64GetA64DynarecCacheTestStats();
	if (stats.build_attempts != 1 || stats.compile_attempts != 0 ||
	    stats.negative_hits != 2 || stats.evictions != 0 || !stats.healthy)
	{
		return fail("negative-hit");
	}
	negative_block[0] = 0x90;
	negative_block[1] = 0x90;
	negative_block[2] = 0x90;
	negative_block[3] = 0x90;
	const bool mutation_compiled = RunUntilA64DynarecCompileForTest([&]
	{
		const auto mutation = run_code(negative_block, 0x5555555555555555ULL, 0);
		return mutation.result == X64RunResult::Returned &&
		       mutation.rax == 0x5555555555555555ULL;
	});
	stats = X64GetA64DynarecCacheTestStats();
	const uint64_t mutation_promotions =
	    stats.delayed_positive_admission ? 1u : 0u;
	if (!mutation_compiled || !A64DynarecLegacyBuildCountMatches(stats, 2) ||
	    stats.compile_attempts != 1 || stats.negative_hits != 2 || stats.evictions != 0 ||
	    stats.admission_promotions != mutation_promotions ||
	    (stats.delayed_positive_admission
	         ? stats.admission_deferrals < mutation_promotions
	         : stats.admission_deferrals != 0) ||
	    !stats.healthy)
	{
		return fail("negative-mutation-count");
	}

	// Poison from a nested Run must survive X64RunContextScope restoration and
	// disable later entries only on this TLS cache. A fresh worker compiles the
	// same block independently and remains healthy.
	X64ResetA64DynarecCacheForTest();
	g_a64_cache_nested_count = 0;
	if (!RunUntilA64DynarecCompileForTest([&]
	    {
		    return run_code(active_block, 0, 0, A64CachePolicyHostCall, 24).result ==
		           X64RunResult::Returned;
	    }) ||
	    !compile_returned_value(block_b, 0x6666666666666666ULL))
	{
		return fail("latch-warm");
	}
	g_a64_cache_nested_rips[0] = reinterpret_cast<uint64_t>(block_b);
	g_a64_cache_nested_rsps[0] = reinterpret_cast<uint64_t>(&memory.stack[4]);
	g_a64_cache_nested_source = reinterpret_cast<uint64_t>(&memory.source);
	g_a64_cache_nested_count = 1;
	X64SetA64DynarecPoisonRipForTest(reinterpret_cast<uint64_t>(block_b));
	const auto poisoned_outer = run_code(active_block, 0, 0x7777777777777777ULL,
	                                     A64CachePolicyHostCall, 24);
	g_a64_cache_nested_count = 0;
	if (poisoned_outer.result != X64RunResult::Returned || poisoned_outer.rip != 0 ||
	    g_a64_cache_nested_results[0] != X64RunResult::Returned ||
	    g_a64_cache_nested_values[0] != 0x7777777777777777ULL ||
	    X64GetA64DynarecCacheTestStats().healthy)
	{
		return fail("latch-nested-poison");
	}
	const auto latched_stats = X64GetA64DynarecCacheTestStats();
	if (!returned_value(block_b, 0x8888888888888888ULL)) return fail("latch-fallback-run");
	stats = X64GetA64DynarecCacheTestStats();
	if (stats.healthy || stats.build_attempts != latched_stats.build_attempts ||
	    stats.compile_attempts != latched_stats.compile_attempts ||
	    stats.positive_hits != latched_stats.positive_hits)
	{
		return fail("latch-sticky");
	}
	bool worker_ok = false;
	std::thread worker([&]()
	{
		X64ResetA64DynarecCacheForTest();
		const bool runs_ok = compile_returned_value(block_b, 0x9999999999999999ULL);
		const auto worker_stats = X64GetA64DynarecCacheTestStats();
		worker_ok = runs_ok && worker_stats.healthy &&
		            A64DynarecLegacyBuildCountMatches(worker_stats, 1) &&
		            worker_stats.compile_attempts == 1 &&
		            A64DynarecCompletedAdmissionsMatch(worker_stats, 1);
		X64ResetA64DynarecCacheForTest();
	});
	worker.join();
	if (!worker_ok || X64GetA64DynarecCacheTestStats().healthy) return fail("latch-tls-isolation");

	// Corrupt both native accounting channels only after the compiled block has
	// changed RAX. InternalError must stop the Run with RAX incremented exactly
	// once; a subsequent Run uses C++ under the sticky latch and is still exact.
	uint8_t* zero_block = code_storage.data() + policy_storage_size - 4096 + 128;
	constexpr std::array<uint8_t, 4> zero_bytes = {0x83, 0xc0, 0x01, 0xc3}; // ADD eax, 1; RET
	std::memcpy(zero_block, zero_bytes.data(), zero_bytes.size());
	X64ResetA64DynarecCacheForTest();
	if (!RunUntilA64DynarecCompileForTest([&]
	    {
		    const auto zero_warm = run_code(zero_block, 10, 0);
		    return zero_warm.result == X64RunResult::Returned && zero_warm.rax == 11 &&
		           zero_warm.rip == 0;
	    }))
	{
		return fail("zero-warm-native");
	}
	X64SetA64DynarecZeroAccountingRipForTest(reinterpret_cast<uint64_t>(zero_block));
	const auto zero_corrupt = run_code(zero_block, 10, 0);
	if (zero_corrupt.result != X64RunResult::InternalError || zero_corrupt.rax != 11 ||
	    zero_corrupt.rip != 0 || X64GetA64DynarecCacheTestStats().healthy)
	{
		return fail("zero-internal-error");
	}
	const auto zero_latched_stats = X64GetA64DynarecCacheTestStats();
	const auto zero_fallback = run_code(zero_block, 10, 0);
	stats = X64GetA64DynarecCacheTestStats();
	if (zero_fallback.result != X64RunResult::Returned || zero_fallback.rax != 11 || zero_fallback.rip != 0 ||
	    stats.healthy || stats.build_attempts != zero_latched_stats.build_attempts ||
	    stats.compile_attempts != zero_latched_stats.compile_attempts ||
	    stats.positive_hits != zero_latched_stats.positive_hits)
	{
		return fail("zero-no-replay-fallback");
	}

	// A Completed exit is valid only when the whole verified block retired and
	// the native resume boundary equals the decoded block end. Corrupt either
	// field after architected effects have committed: the tier must latch off,
	// while ADD remains visible exactly once and the C++ block is never replayed.
	X64ResetA64DynarecCacheForTest();
	if (!RunUntilA64DynarecCompileForTest([&]
	    {
		    const auto warm = run_code(zero_block, 10, 0);
		    return warm.result == X64RunResult::Returned && warm.rax == 11 && warm.rip == 0;
	    }))
	{
		return fail("partial-completed-warm");
	}
	X64SetA64DynarecPartialCompletedRipForTest(reinterpret_cast<uint64_t>(zero_block));
	const auto partial_completed = run_code(zero_block, 10, 0);
	if (partial_completed.result != X64RunResult::Returned || partial_completed.rax != 11 ||
	    partial_completed.rip != 0 || X64GetA64DynarecCacheTestStats().healthy)
	{
		return fail("partial-completed-no-replay");
	}

	X64ResetA64DynarecCacheForTest();
	if (!RunUntilA64DynarecCompileForTest([&]
	    {
		    const auto warm = run_code(zero_block, 10, 0);
		    return warm.result == X64RunResult::Returned && warm.rax == 11 && warm.rip == 0;
	    }))
	{
		return fail("bad-resume-warm");
	}
	X64SetA64DynarecBadResumeRipForTest(reinterpret_cast<uint64_t>(zero_block));
	const auto bad_resume = run_code(zero_block, 10, 0);
	if (bad_resume.result != X64RunResult::Returned || bad_resume.rax != 11 ||
	    bad_resume.rip != 0 || X64GetA64DynarecCacheTestStats().healthy)
	{
		return fail("bad-resume-no-replay");
	}

	X64ResetA64DynarecCacheForTest();
	stats = X64GetA64DynarecCacheTestStats();
	EnableA64Dynarec(false);
	return stats.healthy && stats.build_attempts == 0 && stats.compile_attempts == 0;
}

bool TestF7ArithmeticSemantics()
{
	FastBlocksDisabledForTest fast_blocks_disabled;
	constexpr uint64_t FLAG_CF = 0x001;
	constexpr uint64_t FLAG_PF = 0x004;
	constexpr uint64_t FLAG_ZF = 0x040;
	constexpr uint64_t FLAG_SF = 0x080;
	constexpr uint64_t FLAG_OF = 0x800;
	constexpr uint64_t MUL_FLAGS = FLAG_CF | FLAG_OF;

	auto encode_register = [](uint8_t width, uint8_t group,
	                          std::array<uint8_t, 9>* code)
	{
		code->fill(0x90);
		size_t offset = 0;
		if (width == 2) (*code)[offset++] = 0x66;
		else if (width == 8) (*code)[offset++] = 0x48;
		(*code)[offset++] = 0xf7;
		(*code)[offset++] = static_cast<uint8_t>(0xc1u | (group << 3u));
		(*code)[offset++] = 0xc3;
		return offset;
	};
	auto width_mask = [](uint8_t width)
	{
		return width == 2 ? UINT64_C(0xffff) :
		       (width == 4 ? UINT64_C(0xffffffff) : UINT64_MAX);
	};
	auto merge_result = [&](uint64_t before, uint64_t value, uint8_t width)
	{
		if (width == 2) return (before & ~UINT64_C(0xffff)) | (value & UINT64_C(0xffff));
		if (width == 4) return static_cast<uint64_t>(static_cast<uint32_t>(value));
		return value;
	};

	// In long mode REX.W wins over a redundant operand-size override. Besides
	// checking the result, the TEST form proves that F7 /0 still consumes imm32.
	{
		constexpr std::array<uint8_t, 5> neg_code = {0x66, 0x48, 0xf7, 0xd8, 0xc3};
		X64State state {};
		state.gpr[0] = UINT64_C(0x0001000000000001);
		state.rflags = 0x2;
		if (!Run(neg_code.data(), neg_code.size(), &state) ||
		    state.gpr[0] != UINT64_C(0xfffeffffffffffff))
		{
			return false;
		}

		constexpr std::array<uint8_t, 9> test_code = {
		    0x66, 0x48, 0xf7, 0xc0, 0x00, 0x00, 0x00, 0x80, 0xc3,
		};
		state = {};
		state.gpr[0] = UINT64_C(0x8000000000000000);
		state.rflags = 0x8d7;
		if (!Run(test_code.data(), test_code.size(), &state) ||
		    state.gpr[0] != UINT64_C(0x8000000000000000) ||
		    (state.rflags & (FLAG_CF | FLAG_PF | FLAG_ZF | FLAG_SF | FLAG_OF)) !=
		        (FLAG_PF | FLAG_SF))
		{
			return false;
		}
	}

	struct MultiplyCase
	{
		uint8_t width;
		uint8_t group;
		uint64_t accumulator;
		uint64_t source;
		uint64_t low;
		uint64_t high;
		bool overflow;
	};
	constexpr std::array<MultiplyCase, 12> multiply_cases = {{
	    {2, 4, 3, 4, 12, 0, false},
	    {2, 4, 0xffff, 2, 0xfffe, 1, true},
	    {4, 4, 3, 4, 12, 0, false},
	    {4, 4, 0xffffffff, 2, 0xfffffffe, 1, true},
	    {8, 4, 3, 4, 12, 0, false},
	    {8, 4, UINT64_MAX, 2, UINT64_C(0xfffffffffffffffe), 1, true},
	    {2, 5, 0xfffd, 4, 0xfff4, 0xffff, false},
	    {2, 5, 0x7fff, 2, 0xfffe, 0, true},
	    {4, 5, 0xfffffffd, 4, 0xfffffff4, 0xffffffff, false},
	    {4, 5, 0x7fffffff, 2, 0xfffffffe, 0, true},
	    {8, 5, UINT64_C(0xfffffffffffffffd), 4,
	     UINT64_C(0xfffffffffffffff4), UINT64_MAX, false},
	    {8, 5, UINT64_C(0x7fffffffffffffff), 2,
	     UINT64_C(0xfffffffffffffffe), 0, true},
	}};
	for (const auto& test: multiply_cases)
	{
		std::array<uint8_t, 9> code {};
		const size_t code_size = encode_register(test.width, test.group, &code);
		const uint64_t mask = width_mask(test.width);
		X64State state {};
		const uint64_t accumulator_before =
		    test.width == 2 ? (UINT64_C(0x1122334455660000) | (test.accumulator & mask)) :
		    (test.width == 4 ? (UINT64_C(0xa5a5a5a500000000) | (test.accumulator & mask)) :
		                       test.accumulator);
		const uint64_t high_before = test.width == 2 ? UINT64_C(0x8877665544330000) :
		                             (test.width == 4 ? UINT64_C(0x5a5a5a5a00000000) : 0);
		state.gpr[0] = accumulator_before;
		state.gpr[1] = test.source & mask;
		state.gpr[2] = high_before;
		state.rflags = test.overflow ? UINT64_C(0x246) : UINT64_C(0xa47);
		const uint64_t flags_before = state.rflags;
		if (!Run(code.data(), code_size, &state) ||
		    state.gpr[0] != merge_result(accumulator_before, test.low, test.width) ||
		    state.gpr[2] != merge_result(high_before, test.high, test.width) ||
		    state.rflags != ((flags_before & ~MUL_FLAGS) |
		                     (test.overflow ? MUL_FLAGS : 0)))
		{
			return false;
		}
	}

	struct DivideCase
	{
		uint8_t width;
		uint8_t group;
		uint64_t low;
		uint64_t high;
		uint64_t divisor;
		uint64_t quotient;
		uint64_t remainder;
	};
	constexpr std::array<DivideCase, 6> divide_cases = {{
	    {2, 6, 6, 0, 2, 3, 0},
	    {4, 6, 0, 1, 3, 0x55555555, 1},
	    {8, 6, 0, 1, 3, UINT64_C(0x5555555555555555), 1},
	    {2, 7, 0xfff9, 0xffff, 3, 0xfffe, 0xffff},
	    {4, 7, 0xfffffff9, 0xffffffff, 3, 0xfffffffe, 0xffffffff},
	    {8, 7, UINT64_C(0xfffffffffffffff9), UINT64_MAX, 3,
	     UINT64_C(0xfffffffffffffffe), UINT64_MAX},
	}};
	for (const auto& test: divide_cases)
	{
		std::array<uint8_t, 9> code {};
		const size_t code_size = encode_register(test.width, test.group, &code);
		const uint64_t mask = width_mask(test.width);
		X64State state {};
		const uint64_t low_before =
		    test.width == 2 ? (UINT64_C(0x1122334455660000) | (test.low & mask)) :
		    (test.width == 4 ? (UINT64_C(0xa5a5a5a500000000) | (test.low & mask)) : test.low);
		const uint64_t high_before =
		    test.width == 2 ? (UINT64_C(0x8877665544330000) | (test.high & mask)) :
		    (test.width == 4 ? (UINT64_C(0x5a5a5a5a00000000) | (test.high & mask)) : test.high);
		state.gpr[0] = low_before;
		state.gpr[1] = test.divisor & mask;
		state.gpr[2] = high_before;
		state.rflags = 0x8d7;
		if (!Run(code.data(), code_size, &state) ||
		    state.gpr[0] != merge_result(low_before, test.quotient, test.width) ||
		    state.gpr[2] != merge_result(high_before, test.remainder, test.width) ||
		    state.rflags != 0x8d7)
		{
			return false;
		}
	}

	struct DivideErrorCase
	{
		uint8_t width;
		uint8_t group;
		uint64_t low;
		uint64_t high;
		uint64_t divisor;
	};
	constexpr std::array<DivideErrorCase, 15> divide_error_cases = {{
	    {2, 6, 0, 1, 1},
	    {4, 6, 0, 1, 1},
	    {8, 6, 0, 1, 1},
	    {2, 7, 0, 0x8000, 0xffff},
	    {4, 7, 0, 0x80000000, 0xffffffff},
	    {8, 7, 0, UINT64_C(0x8000000000000000), UINT64_MAX},
	    {2, 7, 0, 1, 1},
	    {4, 7, 0, 1, 1},
	    {8, 7, 0, 1, 1},
	    {2, 6, 0x1234, 0x5678, 0},
	    {4, 6, 0x12345678, 0x9abcdef0, 0},
	    {8, 6, UINT64_C(0x123456789abcdef0), UINT64_C(0x0fedcba987654321), 0},
	    {2, 7, 0x1234, 0x5678, 0},
	    {4, 7, 0x12345678, 0x9abcdef0, 0},
	    {8, 7, UINT64_C(0x123456789abcdef0), UINT64_C(0x0fedcba987654321), 0},
	}};
	for (const auto& test: divide_error_cases)
	{
		std::array<uint8_t, 9> code {};
		encode_register(test.width, test.group, &code);
		const uint64_t mask = width_mask(test.width);
		X64State state {};
		state.gpr[0] = test.width == 2 ? UINT64_C(0x1122334455660000) | (test.low & mask) : test.low;
		state.gpr[1] = test.divisor & mask;
		state.gpr[2] = test.width == 2 ? UINT64_C(0x8877665544330000) | (test.high & mask) : test.high;
		state.gpr[7] = UINT64_C(0x13579bdf2468ace0);
		state.rflags = 0x8d7;
		state.rip = reinterpret_cast<uint64_t>(code.data());
		const X64State before = state;
		if (X64Interpreter {}.Run(&state, 1) != X64RunResult::UnsupportedInstruction ||
		    state.rip != before.rip || state.rflags != before.rflags ||
		    std::memcmp(state.gpr, before.gpr, sizeof(state.gpr)) != 0)
		{
			return false;
		}
	}
	return true;
}

bool TestF7RegisterMemoryMatrix()
{
	FastBlocksDisabledForTest fast_blocks_disabled;
	constexpr uint64_t FLAG_CF = 0x001;
	constexpr uint64_t FLAG_PF = 0x004;
	constexpr uint64_t FLAG_AF = 0x010;
	constexpr uint64_t FLAG_ZF = 0x040;
	constexpr uint64_t FLAG_SF = 0x080;
	constexpr uint64_t FLAG_OF = 0x800;
	constexpr uint64_t RESULT_FLAGS = FLAG_CF | FLAG_PF | FLAG_ZF | FLAG_SF | FLAG_OF;
	constexpr uint64_t ARITHMETIC_FLAGS = RESULT_FLAGS | FLAG_AF;

	auto width_mask = [](uint8_t width)
	{
		return width == 2 ? UINT64_C(0xffff) :
		       (width == 4 ? UINT64_C(0xffffffff) : UINT64_MAX);
	};
	auto merge_result = [](uint64_t before, uint64_t value, uint8_t width)
	{
		if (width == 2) return (before & ~UINT64_C(0xffff)) | (value & UINT64_C(0xffff));
		if (width == 4) return static_cast<uint64_t>(static_cast<uint32_t>(value));
		return value;
	};
	auto encode = [](uint8_t width, uint8_t group, bool memory,
	                 std::array<uint8_t, 10>* code)
	{
		code->fill(0x90);
		size_t offset = 0;
		if (width == 2) (*code)[offset++] = 0x66;
		else if (width == 8) (*code)[offset++] = 0x48;
		(*code)[offset++] = 0xf7;
		(*code)[offset++] = static_cast<uint8_t>((group << 3u) | (memory ? 0x07u : 0xc1u));
		if (group == 0)
		{
			const size_t immediate_size = width == 2 ? 2 : 4;
			for (size_t byte = 0; byte < immediate_size; byte++) (*code)[offset++] = 0xff;
		}
		(*code)[offset++] = 0xc3;
		return offset;
	};
	auto fail = [](const char* stage, uint8_t group, uint8_t width)
	{
		std::fprintf(stderr, "F7 register/memory matrix failure: %s group=%u width=%u\n",
		             stage, group, width);
		return false;
	};

	// This is the complete implemented F7 matrix: every legal group, every
	// operand width and both register and memory r/m forms. The register form is
	// an independent oracle, with explicit result checks preventing a shared
	// decoder error from making both sides agree accidentally.
	for (const uint8_t group: {uint8_t {0}, uint8_t {2}, uint8_t {3}, uint8_t {4},
	                           uint8_t {5}, uint8_t {6}, uint8_t {7}})
	{
		for (const uint8_t width: {uint8_t {2}, uint8_t {4}, uint8_t {8}})
		{
			const uint64_t mask = width_mask(width);
			const uint64_t source = group == 5 ? (mask - 1) : UINT64_C(2);
			const uint64_t source_register_before =
			    (UINT64_C(0xa5a5a5a5a5a5a5a5) & ~mask) | source;
			alignas(8) uint64_t memory_source = source_register_before;

			uint64_t low = UINT64_C(0x1122334455667788) & ~mask;
			uint64_t high = UINT64_C(0x8877665544332211) & ~mask;
			if (group == 4 || group == 5)
			{
				low |= 3;
			} else if (group == 6)
			{
				low |= 7;
			} else if (group == 7)
			{
				low |= mask - 6; // -7 in the selected width
				high |= mask;    // sign extension of the dividend
			}

			X64State register_state {};
			for (uint8_t reg = 0; reg < 16; reg++)
			{
				register_state.gpr[reg] = UINT64_C(0x0102030405060708) ^
				                          (static_cast<uint64_t>(reg) << 52u);
			}
			register_state.gpr[0] = low;
			register_state.gpr[1] = source_register_before;
			register_state.gpr[2] = high;
			register_state.rflags = 0x8d7;
			X64State memory_state = register_state;
			memory_state.gpr[7] = reinterpret_cast<uint64_t>(&memory_source);
			const X64State register_before = register_state;
			const X64State memory_before = memory_state;

			std::array<uint8_t, 10> register_code {};
			std::array<uint8_t, 10> memory_code {};
			const size_t register_size = encode(width, group, false, &register_code);
			const size_t memory_size = encode(width, group, true, &memory_code);
			if (!Run(register_code.data(), register_size, &register_state) ||
			    !Run(memory_code.data(), memory_size, &memory_state))
			{
				return fail("run", group, width);
			}

			uint64_t expected_source = source_register_before;
			uint64_t expected_memory = source_register_before;
			if (group == 2 || group == 3)
			{
				const uint64_t transformed =
				    group == 2 ? (~source & mask) : ((UINT64_C(0) - source) & mask);
				expected_source = merge_result(source_register_before, transformed, width);
				expected_memory = (source_register_before & ~mask) | transformed;
			}
			if (register_state.gpr[1] != expected_source || memory_source != expected_memory)
			{
				return fail("source-result", group, width);
			}

			uint64_t expected_low = low;
			uint64_t expected_high = high;
			if (group == 4)
			{
				expected_low = merge_result(low, 6, width);
				expected_high = merge_result(high, 0, width);
			} else if (group == 5)
			{
				expected_low = merge_result(low, mask - 5, width); // -6
				expected_high = merge_result(high, mask, width);
			} else if (group == 6)
			{
				expected_low = merge_result(low, 3, width);
				expected_high = merge_result(high, 1, width);
			} else if (group == 7)
			{
				expected_low = merge_result(low, mask - 2, width); // -3
				expected_high = merge_result(high, mask, width);   // -1
			}

			uint64_t expected_flags = register_before.rflags;
			if (group == 0)
			{
				// TEST 2, -1: all five defined result flags are clear.
				expected_flags &= ~RESULT_FLAGS;
			} else if (group == 3)
			{
				// NEG 2 produces ...fffe: CF/AF/SF set, PF/ZF/OF clear.
				expected_flags = (expected_flags & ~ARITHMETIC_FLAGS) |
				                 (FLAG_CF | FLAG_AF | FLAG_SF);
			} else if (group == 4 || group == 5)
			{
				expected_flags &= ~(FLAG_CF | FLAG_OF);
			}
			if (register_state.gpr[0] != expected_low || register_state.gpr[2] != expected_high ||
			    memory_state.gpr[0] != expected_low || memory_state.gpr[2] != expected_high ||
			    register_state.rflags != expected_flags || memory_state.rflags != expected_flags)
			{
				return fail("architectural-result", group, width);
			}

			for (uint8_t reg = 0; reg < 16; reg++)
			{
				if (reg == 0 || reg == 1 || reg == 2 || reg == 4 || reg == 7) continue;
				if (register_state.gpr[reg] != register_before.gpr[reg] ||
				    memory_state.gpr[reg] != memory_before.gpr[reg])
				{
					return fail("unrelated-register", group, width);
				}
			}
		}
	}

	// Exercise the shared address decoder with REX.X/REX.B, scaled index and
	// displacement: MUL qword ptr [r12+r13*4+8].
	{
		constexpr std::array<uint8_t, 6> code = {0x4b, 0xf7, 0x64, 0xac, 0x08, 0xc3};
		alignas(8) std::array<uint8_t, 64> data {};
		constexpr uint64_t source = 3;
		std::memcpy(data.data() + 24, &source, sizeof(source));
		X64State state {};
		state.gpr[0] = 4;
		state.gpr[2] = UINT64_MAX;
		state.gpr[12] = reinterpret_cast<uint64_t>(data.data());
		state.gpr[13] = 4;
		state.rflags = 0x8d7;
		if (!Run(code.data(), code.size(), &state) || state.gpr[0] != 12 ||
		    state.gpr[2] != 0 || state.rflags != (UINT64_C(0x8d7) & ~(FLAG_CF | FLAG_OF)))
		{
			return fail("extended-sib", 4, 8);
		}
		uint64_t unchanged = 0;
		std::memcpy(&unchanged, data.data() + 24, sizeof(unchanged));
		if (unchanged != source) return fail("extended-sib-source", 4, 8);
	}
	return true;
}

bool TestF7FastBlockBoundary()
{
	FastBlockTestConfiguration configuration;
	struct FastCase
	{
		uint8_t width;
		uint8_t group;
	};
	constexpr std::array<FastCase, 7> fast_cases = {{
	    {4, 0}, {8, 0}, {4, 2}, {8, 2}, {2, 3}, {4, 3}, {8, 3},
	}};
	alignas(4096) static std::array<std::array<uint8_t, 4096>, fast_cases.size()> code {};
	std::array<uint64_t, 1> return_stack {};

	auto initialize_code = [](const FastCase& test, std::array<uint8_t, 4096>* bytes)
	{
		bytes->fill(0x90);
		size_t offset = 0;
		if (test.width == 2) (*bytes)[offset++] = 0x66;
		else if (test.width == 8) (*bytes)[offset++] = 0x48;
		(*bytes)[offset++] = 0xf7;
		(*bytes)[offset++] = static_cast<uint8_t>(0xc1u | (test.group << 3u));
		if (test.group == 0)
		{
			(*bytes)[offset++] = 0x01;
			(*bytes)[offset++] = 0x00;
			(*bytes)[offset++] = 0x00;
			(*bytes)[offset++] = 0x80;
		}
		(*bytes)[offset] = 0xc3;
	};
	auto execute = [&](const auto& bytes, const FastCase& test, bool fast, X64State* state)
	{
		EnableFastBlocks(fast);
		return_stack[0] = 0;
		*state = {};
		state->rip = reinterpret_cast<uint64_t>(bytes.data());
		state->gpr[0] = test.group == 7 ? UINT64_C(8) : UINT64_C(0x1122334455667788);
		state->gpr[1] = test.group == 3 ? UINT64_C(1) : UINT64_C(0x8000000180000001);
		if (test.group == 7) state->gpr[1] = 2;
		state->gpr[4] = reinterpret_cast<uint64_t>(return_stack.data());
		state->rflags = 0x8d7;
		return X64Interpreter {}.Run(state, 8);
	};
	auto equivalent = [](const X64State& lhs, const X64State& rhs)
	{
		return lhs.rip == rhs.rip && lhs.rflags == rhs.rflags &&
		       std::memcmp(lhs.gpr, rhs.gpr, sizeof(lhs.gpr)) == 0;
	};

	for (size_t index = 0; index < fast_cases.size(); index++)
	{
		initialize_code(fast_cases[index], &code[index]);
		X64State slow {};
		if (execute(code[index], fast_cases[index], false, &slow) != X64RunResult::Returned)
		{
			return false;
		}
		X64State fast {};
		for (uint8_t iteration = 0; iteration < 4; iteration++)
		{
			if (execute(code[index], fast_cases[index], true, &fast) != X64RunResult::Returned)
			{
				return false;
			}
		}
		X64SetFastBlockTestTarget(reinterpret_cast<uint64_t>(code[index].data()));
		if (execute(code[index], fast_cases[index], true, &fast) != X64RunResult::Returned ||
		    X64FastBlockTestTargetInstructionCount() == 0 || !equivalent(slow, fast))
		{
			std::fprintf(stderr, "F7 FastBlock mismatch: group=%u width=%u steps=%llu\n",
			             fast_cases[index].group, fast_cases[index].width,
			             static_cast<unsigned long long>(X64FastBlockTestTargetInstructionCount()));
			return false;
		}
	}

	// IDIV deliberately has no FastOp representation. A hot /7 block must keep
	// using the precise handler and therefore never account a FastBlock step.
	alignas(4096) static constexpr std::array<uint8_t, 4096> idiv_code = {
	    0xf7, 0xf9, // IDIV ecx
	    0xc3,
	};
	const FastCase idiv_case {4, 7};
	X64State idiv_slow {};
	if (execute(idiv_code, idiv_case, false, &idiv_slow) != X64RunResult::Returned ||
	    idiv_slow.gpr[0] != 4 || idiv_slow.gpr[2] != 0)
	{
		return false;
	}
	X64State idiv_fast {};
	for (uint8_t iteration = 0; iteration < 4; iteration++)
	{
		if (execute(idiv_code, idiv_case, true, &idiv_fast) != X64RunResult::Returned)
		{
			return false;
		}
	}
	X64SetFastBlockTestTarget(reinterpret_cast<uint64_t>(idiv_code.data()));
	return execute(idiv_code, idiv_case, true, &idiv_fast) == X64RunResult::Returned &&
	       X64FastBlockTestTargetInstructionCount() == 0 &&
	       equivalent(idiv_slow, idiv_fast);
}

bool TestF7FaultAtomicityAndLockSemantics()
{
	FastBlocksDisabledForTest fast_blocks_disabled;
	constexpr uint64_t ARITHMETIC_FLAGS = 0x8d5;
	constexpr uint64_t NEG_ONE_FLAGS = 0x095;
	auto fail = [](const char* stage, uint8_t group, uint8_t width, bool lock)
	{
		std::fprintf(stderr, "F7 fault/LOCK failure: %s group=%u width=%u lock=%u\n",
		             stage, group, width, lock ? 1u : 0u);
		return false;
	};

	auto encode_memory = [](uint8_t width, uint8_t group, bool lock,
	                        std::array<uint8_t, 4096>* code)
	{
		code->fill(0x90);
		size_t offset = 0;
		if (lock) (*code)[offset++] = 0xf0;
		if (width == 2) (*code)[offset++] = 0x66;
		else if (width == 8) (*code)[offset++] = 0x48;
		(*code)[offset++] = 0xf7;
		(*code)[offset++] = static_cast<uint8_t>(0x07u | (group << 3u));
		if (group == 0)
		{
			const size_t immediate_size = width == 2 ? 2 : 4;
			for (size_t byte = 0; byte < immediate_size; byte++)
			{
				(*code)[offset++] = static_cast<uint8_t>(0xa5u + byte);
			}
		}
		return offset;
	};
	auto width_mask = [](uint8_t width)
	{
		return width == 2 ? UINT64_C(0xffff) :
		       (width == 4 ? UINT64_C(0xffffffff) : UINT64_MAX);
	};

	// Every implemented F7 group must stop immediately after a denied source
	// read. In particular DIV/IDIV must report MemoryFault, not reinterpret the
	// fault value as a zero divisor and return UnsupportedInstruction.
	for (const uint8_t group: {uint8_t {0}, uint8_t {2}, uint8_t {3}, uint8_t {4},
	                           uint8_t {5}, uint8_t {6}, uint8_t {7}})
	{
		for (const uint8_t width: {uint8_t {2}, uint8_t {4}, uint8_t {8}})
		{
			alignas(4096) std::array<uint8_t, 4096> code {};
			encode_memory(width, group, false, &code);
			alignas(8) uint64_t data = UINT64_C(0x1122334455667788);
			X64State state {};
			state.rip = reinterpret_cast<uint64_t>(code.data());
			state.gpr[0] = UINT64_C(0xaabbccddeeff0011);
			state.gpr[2] = UINT64_C(0x123456789abcdef0);
			state.gpr[7] = reinterpret_cast<uint64_t>(&data);
			state.rflags = 0x8d7;
			const X64State before = state;
			g_test_regions = {{
			    {reinterpret_cast<uint64_t>(code.data()),
			     reinterpret_cast<uint64_t>(code.data() + code.size()), true, false},
			    {reinterpret_cast<uint64_t>(&data), reinterpret_cast<uint64_t>(&data) + sizeof(data), false, true},
			}};
			g_observed_data_begin = reinterpret_cast<uint64_t>(&data);
			g_observed_data_end = g_observed_data_begin + sizeof(data);
			g_observed_data_translate_calls = 0;
			const auto result =
			    X64Interpreter(nullptr, TranslateObservedTestRegionAddress).Run(&state, 1);
			g_test_regions = {};
			g_observed_data_begin = 0;
			g_observed_data_end = 0;
			if (result != X64RunResult::MemoryFault || state.rip != before.rip ||
			    state.memory_fault_address != reinterpret_cast<uint64_t>(&data) ||
			    state.memory_fault_size != width || state.memory_fault_write ||
			    state.rflags != before.rflags ||
			    std::memcmp(state.gpr, before.gpr, sizeof(state.gpr)) != 0 ||
			    data != UINT64_C(0x1122334455667788) ||
			    g_observed_data_translate_calls == 0)
			{
				return fail("read-fault", group, width, false);
			}
		}
	}

	// TEST must validate its immediate before observing either flags or a data
	// operand. Cover imm16 and imm32, including REX.W, for both r/m forms.
	for (const uint8_t width: {uint8_t {2}, uint8_t {4}, uint8_t {8}})
	{
		alignas(4096) std::array<uint8_t, 4096> code {};
		size_t offset = 0;
		if (width == 2) code[offset++] = 0x66;
		else if (width == 8) code[offset++] = 0x48;
		code[offset++] = 0xf7;
		code[offset++] = 0xc0; // TEST AX/EAX/RAX, immediate
		const size_t immediate_offset = offset;
		code[offset++] = 0x7f; // leave the final immediate byte(s) inaccessible
		const size_t immediate_size = width == 2 ? 2 : 4;
		X64State state {};
		state.rip = reinterpret_cast<uint64_t>(code.data());
		state.gpr[0] = UINT64_C(0x8877665544332211);
		state.gpr[2] = UINT64_C(0x1020304050607080);
		state.rflags = 0x8d7;
		const X64State before = state;
		g_test_regions = {{
		    {reinterpret_cast<uint64_t>(code.data()),
		     reinterpret_cast<uint64_t>(code.data() + offset), true, false},
		}};
		const auto result = X64Interpreter(nullptr, TranslateTestRegionAddress).Run(&state, 1);
		g_test_regions = {};
		if (result != X64RunResult::MemoryFault || state.rip != before.rip ||
		    state.memory_fault_address != reinterpret_cast<uint64_t>(code.data() + immediate_offset) ||
		    state.memory_fault_size != immediate_size || state.memory_fault_write ||
		    state.rflags != before.rflags ||
		    std::memcmp(state.gpr, before.gpr, sizeof(state.gpr)) != 0)
		{
			return fail("immediate-fault", 0, width, false);
		}

		alignas(4096) std::array<uint8_t, 4096> memory_code {};
		size_t memory_offset = 0;
		if (width == 2) memory_code[memory_offset++] = 0x66;
		else if (width == 8) memory_code[memory_offset++] = 0x48;
		memory_code[memory_offset++] = 0xf7;
		memory_code[memory_offset++] = 0x07; // TEST word/dword/qword ptr [rdi], immediate
		const size_t memory_immediate_offset = memory_offset;
		memory_code[memory_offset++] = 0x7f;
		alignas(8) uint64_t data = UINT64_C(0x1122334455667788);
		state = {};
		state.rip = reinterpret_cast<uint64_t>(memory_code.data());
		state.gpr[0] = UINT64_C(0x8877665544332211);
		state.gpr[2] = UINT64_C(0x1020304050607080);
		state.gpr[7] = reinterpret_cast<uint64_t>(&data);
		state.rflags = 0x8d7;
		const X64State memory_before = state;
		g_test_regions = {{
		    {reinterpret_cast<uint64_t>(memory_code.data()),
		     reinterpret_cast<uint64_t>(memory_code.data() + memory_offset), true, false},
		    {reinterpret_cast<uint64_t>(&data), reinterpret_cast<uint64_t>(&data) + sizeof(data), true, false},
		}};
		g_observed_data_begin = reinterpret_cast<uint64_t>(&data);
		g_observed_data_end = g_observed_data_begin + sizeof(data);
		g_observed_data_translate_calls = 0;
		const auto memory_result =
		    X64Interpreter(nullptr, TranslateObservedTestRegionAddress).Run(&state, 1);
		g_test_regions = {};
		g_observed_data_begin = 0;
		g_observed_data_end = 0;
		if (memory_result != X64RunResult::MemoryFault || state.rip != memory_before.rip ||
		    state.memory_fault_address !=
		        reinterpret_cast<uint64_t>(memory_code.data() + memory_immediate_offset) ||
		    state.memory_fault_size != immediate_size || state.memory_fault_write ||
		    state.rflags != memory_before.rflags ||
		    std::memcmp(state.gpr, memory_before.gpr, sizeof(state.gpr)) != 0 ||
		    data != UINT64_C(0x1122334455667788) || g_observed_data_translate_calls != 0)
		{
			return fail("memory-immediate-fault-order", 0, width, false);
		}
	}

	// Both ordinary and LOCKed memory RMWs must preserve memory, GPRs and flags
	// when the read succeeds but the write preflight fails.
	for (const bool lock: {false, true})
	{
		for (const uint8_t group: {uint8_t {2}, uint8_t {3}})
		{
			for (const uint8_t width: {uint8_t {2}, uint8_t {4}, uint8_t {8}})
			{
				alignas(4096) std::array<uint8_t, 4096> code {};
				encode_memory(width, group, lock, &code);
				alignas(8) uint64_t data = UINT64_C(0x1122334455660001);
				X64State state {};
				state.rip = reinterpret_cast<uint64_t>(code.data());
				state.gpr[0] = UINT64_C(0xaabbccddeeff0011);
				state.gpr[2] = UINT64_C(0x123456789abcdef0);
				state.gpr[7] = reinterpret_cast<uint64_t>(&data);
				state.rflags = 0x8d7;
				const X64State before = state;
				g_test_regions = {{
				    {reinterpret_cast<uint64_t>(code.data()),
				     reinterpret_cast<uint64_t>(code.data() + code.size()), true, false},
				    {reinterpret_cast<uint64_t>(&data), reinterpret_cast<uint64_t>(&data) + sizeof(data), true, false},
				}};
				const auto result = X64Interpreter(nullptr, TranslateTestRegionAddress).Run(&state, 1);
				g_test_regions = {};
				if (result != X64RunResult::MemoryFault || state.rip != before.rip ||
				    state.memory_fault_address != reinterpret_cast<uint64_t>(&data) ||
				    state.memory_fault_size != width || !state.memory_fault_write ||
				    state.rflags != before.rflags ||
				    std::memcmp(state.gpr, before.gpr, sizeof(state.gpr)) != 0 ||
				    data != UINT64_C(0x1122334455660001))
				{
					return fail("write-fault", group, width, lock);
				}
			}
		}
	}

	// The legal LOCK forms execute as one atomic transform. Verify all operand
	// widths and that NOT preserves flags while NEG reports flags for the value
	// actually replaced by the atomic operation.
	for (const uint8_t group: {uint8_t {2}, uint8_t {3}})
	{
		for (const uint8_t width: {uint8_t {2}, uint8_t {4}, uint8_t {8}})
		{
			alignas(4096) std::array<uint8_t, 4096> code {};
			encode_memory(width, group, true, &code);
			alignas(8) uint64_t data =
			    width == 2 ? UINT64_C(0x1122334455660001) :
			    (width == 4 ? UINT64_C(0x1122334400000001) : UINT64_C(1));
			const uint64_t before_data = data;
			const uint64_t mask = width_mask(width);
			const uint64_t transformed = group == 2 ? (~before_data & mask) : mask;
			const uint64_t expected_data = (before_data & ~mask) | transformed;
			X64State state {};
			state.rip = reinterpret_cast<uint64_t>(code.data());
			state.gpr[7] = reinterpret_cast<uint64_t>(&data);
			state.rflags = 0x246;
			g_test_regions = {{
			    {reinterpret_cast<uint64_t>(code.data()),
			     reinterpret_cast<uint64_t>(code.data() + code.size()), true, false},
			    {reinterpret_cast<uint64_t>(&data), reinterpret_cast<uint64_t>(&data) + sizeof(data), true, true},
			}};
			const auto result = X64Interpreter(nullptr, TranslateTestRegionAddress).Run(&state, 1);
			g_test_regions = {};
			const uint64_t expected_flags =
			    group == 2 ? UINT64_C(0x246) :
			                 ((UINT64_C(0x246) & ~ARITHMETIC_FLAGS) | NEG_ONE_FLAGS);
			if (result != X64RunResult::StepLimit || data != expected_data ||
			    state.rflags != expected_flags)
			{
				return fail("lock-success", group, width, true);
			}
		}
	}

	// Reserved /1 and illegal LOCK groups fail before the data translator is
	// consulted, even when their ModRM names a readable/writable address.
	struct InvalidMemoryCase
	{
		uint8_t group;
		bool lock;
	};
	constexpr std::array<InvalidMemoryCase, 7> invalid_memory_cases = {{
	    {1, false}, {0, true}, {1, true}, {4, true}, {5, true}, {6, true}, {7, true},
	}};
	for (const auto& test: invalid_memory_cases)
	{
		alignas(4096) std::array<uint8_t, 4096> code {};
		encode_memory(4, test.group, test.lock, &code);
		alignas(8) uint64_t data = UINT64_C(0x1122334455667788);
		X64State state {};
		state.rip = reinterpret_cast<uint64_t>(code.data());
		state.gpr[0] = UINT64_C(0xaabbccddeeff0011);
		state.gpr[2] = UINT64_C(0x123456789abcdef0);
		state.gpr[7] = reinterpret_cast<uint64_t>(&data);
		state.rflags = 0x8d7;
		const X64State before = state;
		g_test_regions = {{
		    {reinterpret_cast<uint64_t>(code.data()),
		     reinterpret_cast<uint64_t>(code.data() + code.size()), true, false},
		    {reinterpret_cast<uint64_t>(&data), reinterpret_cast<uint64_t>(&data) + sizeof(data), true, true},
		}};
		g_observed_data_begin = reinterpret_cast<uint64_t>(&data);
		g_observed_data_end = g_observed_data_begin + sizeof(data);
		g_observed_data_translate_calls = 0;
		const auto result =
		    X64Interpreter(nullptr, TranslateObservedTestRegionAddress).Run(&state, 1);
		g_test_regions = {};
		g_observed_data_begin = 0;
		g_observed_data_end = 0;
		if (result != X64RunResult::UnsupportedInstruction || state.rip != before.rip ||
		    state.rflags != before.rflags ||
		    std::memcmp(state.gpr, before.gpr, sizeof(state.gpr)) != 0 ||
		    data != UINT64_C(0x1122334455667788) ||
		    g_observed_data_translate_calls != 0)
		{
			return fail("invalid-memory", test.group, 4, test.lock);
		}
	}

	// LOCK on the register forms of NOT/NEG is also invalid for every width.
	for (const uint8_t group: {uint8_t {2}, uint8_t {3}})
	{
		for (const uint8_t width: {uint8_t {2}, uint8_t {4}, uint8_t {8}})
		{
			std::array<uint8_t, 6> code {};
			size_t offset = 0;
			code[offset++] = 0xf0;
			if (width == 2) code[offset++] = 0x66;
			else if (width == 8) code[offset++] = 0x48;
			code[offset++] = 0xf7;
			code[offset++] = static_cast<uint8_t>(0xc0u | (group << 3u));
			X64State state {};
			state.rip = reinterpret_cast<uint64_t>(code.data());
			state.gpr[0] = UINT64_C(0x1122334455667788);
			state.rflags = 0x8d7;
			const X64State before = state;
			if (X64Interpreter {}.Run(&state, 1) != X64RunResult::UnsupportedInstruction ||
			    state.rip != before.rip || state.rflags != before.rflags ||
			    std::memcmp(state.gpr, before.gpr, sizeof(state.gpr)) != 0)
			{
				return fail("invalid-register", group, width, true);
			}
		}
	}
	return true;
}

bool TestF7LockConcurrent()
{
	FastBlocksDisabledForTest fast_blocks_disabled;
	constexpr std::array<uint8_t, 10> lock_not_code = {
	    0xf0, 0x48, 0xf7, 0x10, // loop: LOCK NOT qword ptr [rax]
	    0x83, 0xea, 0x01,       // SUB edx, 1
	    0x75, 0xf7,             // JNE loop
	    0xc3,
	};
	constexpr std::array<uint8_t, 10> lock_neg_code = {
	    0xf0, 0x48, 0xf7, 0x18, // loop: LOCK NEG qword ptr [rax]
	    0x83, 0xea, 0x01,       // SUB edx, 1
	    0x75, 0xf7,             // JNE loop
	    0xc3,
	};
	constexpr uint32_t thread_count = 5;
	constexpr uint32_t iterations = 5001;
	static_assert((static_cast<uint64_t>(thread_count) * iterations & 1u) != 0,
	              "the F7 contention probe requires an odd transform count");

	auto verify = [&](const auto& code, uint64_t initial, uint64_t expected)
	{
		alignas(8) uint64_t value = initial;
		std::atomic<uint32_t> ready {0};
		std::atomic<bool> start {false};
		std::array<bool, thread_count> succeeded {};
		std::array<std::thread, thread_count> workers {};
		for (uint32_t thread = 0; thread < thread_count; thread++)
		{
			workers[thread] = std::thread(
			    [&, thread]
			    {
				    uint64_t return_address = 0;
				    X64State state {};
				    state.rip = reinterpret_cast<uint64_t>(code.data());
				    state.gpr[0] = reinterpret_cast<uint64_t>(&value);
				    state.gpr[2] = iterations;
				    state.gpr[4] = reinterpret_cast<uint64_t>(&return_address);
				    ready.fetch_add(1, std::memory_order_release);
				    while (!start.load(std::memory_order_acquire)) std::this_thread::yield();
				    succeeded[thread] =
				        X64Interpreter {}.Run(&state, static_cast<size_t>(iterations) * 3u + 1u) ==
				            X64RunResult::Returned &&
				        state.rip == 0;
			    });
		}
		while (ready.load(std::memory_order_acquire) != thread_count) std::this_thread::yield();
		start.store(true, std::memory_order_release);
		for (auto& worker: workers) worker.join();
		for (const bool result: succeeded)
		{
			if (!result) return false;
		}
		return value == expected;
	};
	return verify(lock_not_code, UINT64_C(0x0123456789abcdef),
	              UINT64_C(0xfedcba9876543210)) &&
	       verify(lock_neg_code, 7, static_cast<uint64_t>(-INT64_C(7)));
}

#if defined(LUMEN_FAST_BLOCK_TELEMETRY)
bool TestFastBlockTelemetry()
{
	FastBlockTestConfiguration configuration;
	EnableFastBlockChaining(true);
	EnableA64Dynarec(false);
	if (!X64ValidateFastBlockTelemetryDeadRflagsNormalizationForTest())
	{
		std::fprintf(stderr,
		             "FastBlock telemetry dead-RFLAGS normalization failed\n");
		return false;
	}

	// The family key retains width, opcode group and register-vs-memory form,
	// but deliberately excludes RIP, register identity, displacement and
	// immediate payloads.
	constexpr std::array<uint8_t, 2> neg_eax = {0xf7, 0xd8};
	constexpr std::array<uint8_t, 2> neg_ebx = {0xf7, 0xdb};
	constexpr std::array<uint8_t, 3> neg_r11d = {0x41, 0xf7, 0xdb};
	constexpr std::array<uint8_t, 3> neg_rax = {0x48, 0xf7, 0xd8};
	constexpr std::array<uint8_t, 2> not_eax = {0xf7, 0xd0};
	constexpr std::array<uint8_t, 2> neg_memory = {0xf7, 0x18};
	constexpr std::array<uint8_t, 7> mov_memory_a = {
	    0xc7, 0x40, 0x04, 0x11, 0x22, 0x33, 0x44,
	};
	constexpr std::array<uint8_t, 7> mov_memory_b = {
	    0xc7, 0x43, 0x7f, 0xaa, 0xbb, 0xcc, 0xdd,
	};
	constexpr std::array<uint8_t, 4> vex_no_modrm_a = {
	    0xc5, 0xf8, 0x77, 0xc0,
	};
	constexpr std::array<uint8_t, 4> vex_no_modrm_b = {
	    0xc5, 0xf8, 0x77, 0x00,
	};
	constexpr std::array<uint8_t, 5> vex_group_rm0 = {
	    0xc5, 0xf9, 0x71, 0xd0, 0x01,
	};
	constexpr std::array<uint8_t, 5> vex_group_rm3 = {
	    0xc5, 0xf9, 0x71, 0xd3, 0x01,
	};
	constexpr std::array<uint8_t, 5> vex_group_four = {
	    0xc5, 0xf9, 0x71, 0xe0, 0x01,
	};
	constexpr std::array<uint8_t, 5> vex_map_0f38 = {
	    0xc4, 0xe2, 0x79, 0x00, 0xc0,
	};
	constexpr std::array<uint8_t, 5> vex_map_0f3a = {
	    0xc4, 0xe3, 0x79, 0x00, 0xc0,
	};
	constexpr std::array<uint8_t, 5> popcnt16 = {
	    0x66, 0xf3, 0x0f, 0xb8, 0xc0,
	};
	constexpr std::array<uint8_t, 5> popcnt16_reordered = {
	    0xf3, 0x66, 0x0f, 0xb8, 0xc0,
	};
	constexpr std::array<uint8_t, 4> popcnt32 = {
	    0xf3, 0x0f, 0xb8, 0xc0,
	};
	constexpr std::array<uint8_t, 2> x87_fadd_memory_rax = {0xd8, 0x00};
	constexpr std::array<uint8_t, 2> x87_fadd_memory_rbx = {0xd8, 0x03};
	constexpr std::array<uint8_t, 2> x87_fmul_memory = {0xd8, 0x08};
	constexpr std::array<uint8_t, 2> x87_fadd_st0 = {0xd8, 0xc0};
	constexpr std::array<uint8_t, 2> x87_fadd_st3 = {0xd8, 0xc3};
	constexpr std::array<uint8_t, 2> x87_fchs = {0xd9, 0xe0};
	constexpr std::array<uint8_t, 2> x87_fabs = {0xd9, 0xe1};
	constexpr std::array<uint8_t, 1> truncated_f7 = {0xf7};
	const auto family = [](const auto& bytes)
	{
		return X64NormalizeFastBlockRejectFamilyForTest(bytes.data(),
		                                                  bytes.size());
	};
	const uint64_t neg32_family = family(neg_eax);
	if (neg32_family == 0 || family(neg_ebx) != neg32_family ||
	    family(neg_r11d) != neg32_family || family(neg_rax) == neg32_family ||
	    family(not_eax) == neg32_family || family(neg_memory) == neg32_family ||
	    family(mov_memory_a) == 0 || family(mov_memory_a) != family(mov_memory_b) ||
	    family(vex_no_modrm_a) == 0 ||
	    family(vex_no_modrm_a) != family(vex_no_modrm_b) ||
	    family(vex_group_rm0) == 0 ||
	    family(vex_group_rm0) != family(vex_group_rm3) ||
	    family(vex_group_rm0) == family(vex_group_four) ||
	    family(vex_map_0f38) == 0 ||
	    family(vex_map_0f38) == family(vex_map_0f3a) ||
	    family(popcnt16) == 0 || family(popcnt32) == 0 ||
	    family(popcnt16) != family(popcnt16_reordered) ||
	    family(popcnt16) == family(popcnt32) ||
	    family(x87_fadd_memory_rax) == 0 ||
	    family(x87_fadd_memory_rax) != family(x87_fadd_memory_rbx) ||
	    family(x87_fadd_memory_rax) == family(x87_fmul_memory) ||
	    family(x87_fadd_st0) == 0 ||
	    family(x87_fadd_st0) != family(x87_fadd_st3) ||
	    family(x87_fchs) == 0 || family(x87_fchs) == family(x87_fabs) ||
	    family(truncated_f7) != 0)
	{
		std::fprintf(stderr, "FastBlock telemetry family normalization failed\n");
		return false;
	}

	const auto run_program = [](const uint8_t* code, size_t max_steps,
	                            uint32_t eax, uint32_t ecx, uint32_t edx)
	{
		uint64_t return_address = 0;
		X64State state {};
		state.rip = reinterpret_cast<uint64_t>(code);
		state.gpr[0] = eax;
		state.gpr[1] = ecx;
		state.gpr[2] = edx;
		state.gpr[4] = reinterpret_cast<uint64_t>(&return_address);
		return X64Interpreter {}.Run(&state, max_steps) == X64RunResult::Returned &&
		       state.rip == 0;
	};

	// Two separate Run calls contribute to the same process-wide counters. Once
	// the supported XOR/RET block becomes hot, labels are counted only for the ordinary
	// executor and never again through a recognizer wrapper.
	alignas(4096) std::array<uint8_t, 4096> ordinary_code {};
	ordinary_code[0] = 0x31;
	ordinary_code[1] = 0xc0;
	ordinary_code[2] = 0xc3;
	X64ResetFastBlockTelemetryForTest(1000, 1000);
	if (!run_program(ordinary_code.data(), 3, 7, 0, 0)) return false;
	const X64FastBlockTelemetryTestStats ordinary_first =
	    X64GetFastBlockTelemetryTestStats();
	if (!run_program(ordinary_code.data(), 3, 7, 0, 0)) return false;
	const X64FastBlockTelemetryTestStats ordinary_second =
	    X64GetFastBlockTelemetryTestStats();
	using TelemetryFastOpKind = Lumen::Cpu::X64Fast::FastOpKind;
	const uint64_t expected_ordinary_pair =
	    (static_cast<uint64_t>(TelemetryFastOpKind::XorReg32) << 8u) |
	    static_cast<uint64_t>(TelemetryFastOpKind::Ret);
	if (ordinary_second.attempts <= ordinary_first.attempts ||
	    ordinary_second.hits != 1 || ordinary_second.instructions != 2 ||
	    ordinary_second.ordinary_blocks != 1 ||
	    ordinary_second.operation_labels != 2 ||
	    ordinary_second.pair_labels != 1 || ordinary_second.pair_count != 1 ||
	    ordinary_second.top_pair_key != expected_ordinary_pair ||
	    ordinary_second.top_pair_count != 1 ||
	    ordinary_second.kind_count != 2 ||
	    ordinary_second.recognizer_count != 0 ||
	    ordinary_second.recognizer_steps != 0 || ordinary_second.dropped != 0)
	{
		std::fprintf(stderr,
		             "FastBlock telemetry ordinary accounting failed: "
		             "attempts=%llu/%llu hits=%llu instructions=%llu "
		             "blocks=%llu labels=%llu pairs=%llu/%llu "
		             "top_pair=%llx/%llu recognizers=%llu/%llu dropped=%llu\n",
		             static_cast<unsigned long long>(ordinary_first.attempts),
		             static_cast<unsigned long long>(ordinary_second.attempts),
		             static_cast<unsigned long long>(ordinary_second.hits),
		             static_cast<unsigned long long>(ordinary_second.instructions),
		             static_cast<unsigned long long>(ordinary_second.ordinary_blocks),
		             static_cast<unsigned long long>(ordinary_second.operation_labels),
		             static_cast<unsigned long long>(ordinary_second.pair_labels),
		             static_cast<unsigned long long>(ordinary_second.pair_count),
		             static_cast<unsigned long long>(ordinary_second.top_pair_key),
		             static_cast<unsigned long long>(ordinary_second.top_pair_count),
		             static_cast<unsigned long long>(ordinary_second.recognizer_count),
		             static_cast<unsigned long long>(ordinary_second.recognizer_steps),
		             static_cast<unsigned long long>(ordinary_second.dropped));
		return false;
	}
	if (!X64ValidateFastBlockTelemetrySnapshotFormatForTest())
	{
		std::fprintf(stderr,
		             "FastBlock telemetry pair snapshot format failed\n");
		return false;
	}

	// IDIV is supported by the precise interpreter but intentionally absent
	// from FastBlock F7 groups. NOP makes the true miss occur at offset one;
	// the fresh rejection and later negative-cache hit must aggregate under
	// IDIV's normalized family, never the block-head NOP.
	alignas(4096) std::array<uint8_t, 4096> reject_code {};
	reject_code[0] = 0x90;
	reject_code[1] = 0xf7;
	reject_code[2] = 0xf9;
	reject_code[3] = 0xc3;
	constexpr std::array<uint8_t, 2> idiv_ecx = {0xf7, 0xf9};
	constexpr std::array<uint8_t, 1> nop = {0x90};
	const uint64_t idiv_family = family(idiv_ecx);
	X64ResetFastBlockTelemetryForTest(1000, 1000);
	if (!run_program(reject_code.data(), 3, 8, 2, 0)) return false;
	const X64FastBlockTelemetryTestStats reject_first =
	    X64GetFastBlockTelemetryTestStats();
	if (!run_program(reject_code.data(), 3, 8, 2, 0)) return false;
	const X64FastBlockTelemetryTestStats reject_fresh =
	    X64GetFastBlockTelemetryTestStats();
	if (!run_program(reject_code.data(), 3, 8, 2, 0)) return false;
	const X64FastBlockTelemetryTestStats reject_cached =
	    X64GetFastBlockTelemetryTestStats();
	if (idiv_family == 0 || idiv_family == family(nop) ||
	    reject_fresh.attempts <= reject_first.attempts ||
	    reject_fresh.rejected_attempts == 0 ||
	    reject_fresh.top_reject_key != idiv_family ||
	    reject_fresh.reject_family_count != 1 ||
	    reject_cached.attempts <= reject_fresh.attempts ||
	    reject_cached.rejected_attempts <= reject_fresh.rejected_attempts ||
	    reject_cached.top_reject_key != idiv_family ||
	    reject_cached.top_reject_count <= reject_fresh.top_reject_count ||
	    reject_cached.dropped != 0 || reject_cached.dropped_sidecar != 0)
	{
		std::fprintf(stderr,
		             "FastBlock telemetry negative-cache attribution failed: "
		             "attempts=%llu/%llu/%llu rejects=%llu/%llu "
		             "family=%llx/%llx count=%llu/%llu dropped=%llu/%llu\n",
		             static_cast<unsigned long long>(reject_first.attempts),
		             static_cast<unsigned long long>(reject_fresh.attempts),
		             static_cast<unsigned long long>(reject_cached.attempts),
		             static_cast<unsigned long long>(reject_fresh.rejected_attempts),
		             static_cast<unsigned long long>(reject_cached.rejected_attempts),
		             static_cast<unsigned long long>(idiv_family),
		             static_cast<unsigned long long>(reject_cached.top_reject_key),
		             static_cast<unsigned long long>(reject_fresh.top_reject_count),
		             static_cast<unsigned long long>(reject_cached.top_reject_count),
		             static_cast<unsigned long long>(reject_cached.dropped),
		             static_cast<unsigned long long>(reject_cached.dropped_sidecar));
		return false;
	}
	// Mutating a byte in the negative entry's cached head is SMC for that
	// attempt. The stale sidecar is excluded before the entry is cleared; only
	// the unchanged IDIV entry at its own RIP remains attributable.
	reject_code[0] = 0xfc; // CLD replaces the one-byte NOP.
	if (!run_program(reject_code.data(), 3, 8, 2, 0)) return false;
	const X64FastBlockTelemetryTestStats reject_head_mutated =
	    X64GetFastBlockTelemetryTestStats();
	if (reject_head_mutated.excluded_smc != reject_cached.excluded_smc + 1 ||
	    reject_head_mutated.rejected_attempts !=
	        reject_cached.rejected_attempts + 1 ||
	    reject_head_mutated.top_reject_key != idiv_family ||
	    reject_head_mutated.top_reject_count != reject_cached.top_reject_count + 1 ||
	    reject_head_mutated.dropped != reject_cached.dropped)
	{
		std::fprintf(stderr,
		             "FastBlock telemetry negative-head SMC accounting failed\n");
		return false;
	}
	reject_code[0] = 0x90;
	if (!X64ValidateFastBlockTelemetrySnapshotFormatForTest())
	{
		std::fprintf(stderr,
		             "FastBlock telemetry snapshot framing/checksum failed\n");
		return false;
	}

	// A supported chained predecessor may discover the negative successor after
	// already retiring work. Attribution is deferred until the outer dispatcher
	// retries that successor, yielding exactly one reject per dynamic occurrence.
	alignas(4096) std::array<uint8_t, 4096> chained_reject_code {};
	chained_reject_code[0] = 0xeb;
	chained_reject_code[1] = 0x0e;
	chained_reject_code[16] = 0xf7;
	chained_reject_code[17] = 0xf9;
	chained_reject_code[18] = 0xc3;
	X64ResetFastBlockTelemetryForTest(1000, 1000);
	if (!run_program(chained_reject_code.data(), 3, 8, 2, 0) ||
	    !run_program(chained_reject_code.data(), 3, 8, 2, 0))
	{
		return false;
	}
	const X64FastBlockTelemetryTestStats chained_before =
	    X64GetFastBlockTelemetryTestStats();
	if (!run_program(chained_reject_code.data(), 3, 8, 2, 0)) return false;
	const X64FastBlockTelemetryTestStats chained_after =
	    X64GetFastBlockTelemetryTestStats();
	if (chained_after.rejected_attempts != chained_before.rejected_attempts + 1 ||
	    chained_after.top_reject_key != idiv_family ||
	    chained_after.top_reject_count != chained_before.top_reject_count + 1 ||
	    chained_after.dropped != 0)
	{
		std::fprintf(stderr,
		             "FastBlock telemetry chained reject double-counted\n");
		return false;
	}

	// A short residual sample is accepted when it contains enough bytes to
	// identify the family. An opcode that ends before its required ModRM is
	// explicitly dropped instead of becoming a misleading truncated family.
	X64ResetFastBlockTelemetryForTest(1000, 1000);
	X64RecordFastBlockRejectSampleForTest(idiv_ecx.data(), idiv_ecx.size());
	const X64FastBlockTelemetryTestStats short_complete =
	    X64GetFastBlockTelemetryTestStats();
	X64RecordFastBlockRejectSampleForTest(truncated_f7.data(),
	                                      truncated_f7.size());
	const X64FastBlockTelemetryTestStats short_truncated =
	    X64GetFastBlockTelemetryTestStats();
	if (short_complete.rejected_attempts != 1 || short_complete.dropped != 0 ||
	    short_complete.reject_family_count != 1 ||
	    short_complete.top_reject_key != idiv_family ||
	    short_truncated.rejected_attempts != 1 ||
	    short_truncated.dropped_unclassified != 1 ||
	    short_truncated.dropped != 1 ||
	    short_truncated.top_reject_key != idiv_family ||
	    short_truncated.top_reject_count != short_complete.top_reject_count)
	{
		std::fprintf(stderr,
		             "FastBlock telemetry residual reject accounting failed\n");
		return false;
	}

	// At exactly 15 bytes before the page end, fourteen supported NOPs followed
	// by a truncated CALL can decode against guard padding but cannot name a real
	// miss in the mapped bytes. Fresh and cached negative entries are excluded as
	// known-untracked, not attributed or dropped.
	alignas(4096) std::array<uint8_t, 8192> untracked_code {};
	uint8_t* const untracked_entry = untracked_code.data() + 4096 - 15;
	std::memset(untracked_entry, 0x90, 14);
	untracked_entry[14] = 0xe8;
	auto run_untracked = [&]
	{
		X64State state {};
		state.rip = reinterpret_cast<uint64_t>(untracked_entry);
		return X64Interpreter {}.Run(&state, 1) == X64RunResult::StepLimit &&
		       state.rip == reinterpret_cast<uint64_t>(untracked_entry + 1);
	};
	X64ResetFastBlockTelemetryForTest(1000, 1000);
	if (!run_untracked()) return false;
	const X64FastBlockTelemetryTestStats untracked_first =
	    X64GetFastBlockTelemetryTestStats();
	if (!run_untracked()) return false;
	const X64FastBlockTelemetryTestStats untracked_fresh =
	    X64GetFastBlockTelemetryTestStats();
	if (!run_untracked()) return false;
	const X64FastBlockTelemetryTestStats untracked_cached =
	    X64GetFastBlockTelemetryTestStats();
	if (untracked_fresh.excluded_untracked !=
	        untracked_first.excluded_untracked + 1 ||
	    untracked_cached.excluded_untracked !=
	        untracked_fresh.excluded_untracked + 1 ||
	    untracked_cached.rejected_attempts != 0 ||
	    untracked_cached.reject_family_count != 0 ||
	    untracked_cached.dropped != 0)
	{
		std::fprintf(stderr,
		             "FastBlock telemetry untracked reject accounting failed\n");
		return false;
	}

	// The cached head signature covers 16 bytes. Put the actual decoder miss
	// beyond it, then mutate either the miss or either byte in the gap after the
	// head. No stale sidecar family may receive another valid sample.
	alignas(4096) std::array<uint8_t, 4096> distant_reject_code {};
	auto reset_distant_reject_code = [&]
	{
		distant_reject_code.fill(0);
		for (size_t offset = 0; offset < 18; offset += 3)
		{
			distant_reject_code[offset] = 0x48;
			distant_reject_code[offset + 1] = 0x89;
			distant_reject_code[offset + 2] = 0xc0;
		}
		distant_reject_code[18] = 0xf7;
		distant_reject_code[19] = 0xf9;
		distant_reject_code[20] = 0xc3;
	};
	auto run_distant_reject = [&](uint32_t* eax)
	{
		uint64_t return_address = 0;
		X64State state {};
		state.rip = reinterpret_cast<uint64_t>(distant_reject_code.data());
		state.gpr[0] = 8;
		state.gpr[1] = 2;
		state.gpr[2] = 0;
		state.gpr[4] = reinterpret_cast<uint64_t>(&return_address);
		const bool returned =
		    X64Interpreter {}.Run(&state, 8) == X64RunResult::Returned &&
		    state.rip == 0;
		if (eax != nullptr) *eax = static_cast<uint32_t>(state.gpr[0]);
		return returned;
	};
	auto verify_distant_mutation = [&](size_t mutation_offset,
	                                    uint8_t replacement,
	                                    uint32_t expected_eax,
	                                    uint64_t expected_family_increment)
	{
		reset_distant_reject_code();
		X64ResetFastBlockTelemetryForTest(1000, 1000);
		uint32_t distant_eax = 0;
		if (!run_distant_reject(&distant_eax) || distant_eax != 4 ||
		    !run_distant_reject(&distant_eax) || distant_eax != 4 ||
		    !run_distant_reject(&distant_eax) || distant_eax != 4)
		{
			return false;
		}
		const X64FastBlockTelemetryTestStats distant_cached =
		    X64GetFastBlockTelemetryTestStats();
		if (distant_cached.top_reject_key != idiv_family ||
		    distant_cached.top_reject_count == 0 || distant_cached.dropped != 0)
		{
			return false;
		}
		distant_reject_code[mutation_offset] = replacement;
		if (!run_distant_reject(&distant_eax) || distant_eax != expected_eax)
			return false;
		const X64FastBlockTelemetryTestStats distant_mutated =
		    X64GetFastBlockTelemetryTestStats();
		const uint64_t excluded_delta =
		    distant_mutated.excluded_smc - distant_cached.excluded_smc;
		if (excluded_delta == 0 ||
		    distant_mutated.rejected_attempts !=
		        distant_cached.rejected_attempts + expected_family_increment ||
		    distant_mutated.dropped != distant_cached.dropped ||
		    distant_mutated.top_reject_key != idiv_family ||
		    distant_mutated.top_reject_count !=
		        distant_cached.top_reject_count + expected_family_increment)
		{
			std::fprintf(
			    stderr,
			    "FastBlock telemetry distant mutation validation failed: offset=%zu\n",
			    mutation_offset);
			return false;
		}
		return true;
	};
	// Changing the final MOV ModRM at offset 17 still reaches the real IDIV at
	// its own RIP, so exactly that later dynamic reject remains attributable.
	if (!verify_distant_mutation(19, 0xd8, UINT32_C(0xfffffff8), 0) ||
	    !verify_distant_mutation(16, 0xc3, 8, 0) ||
	    !verify_distant_mutation(17, 0xc3, 4, 1))
	{
		return false;
	}

	// The sparse kind list is bounded by the complete kind domain. Its defensive
	// overflow path must invalidate telemetry without writing past the list.
	X64ResetFastBlockTelemetryForTest(1000, 1000);
	X64RecordFastBlockTelemetryTouchedOverflowForTest();
	const X64FastBlockTelemetryTestStats touched_overflow =
	    X64GetFastBlockTelemetryTestStats();
	if (!touched_overflow.enabled || touched_overflow.finalized ||
	    touched_overflow.attempts != 1 || touched_overflow.operation_labels != 0 ||
	    touched_overflow.kind_count != 0 ||
	    touched_overflow.dropped_internal != 1 || touched_overflow.dropped != 1)
	{
		std::fprintf(stderr,
		             "FastBlock telemetry touched-kind overflow was not fail-closed\n");
		return false;
	}

	constexpr std::array<uint8_t, 1> config_mismatch_code = {0xc3};
	auto run_config_mismatch = [&]
	{
		uint64_t return_address = 0;
		X64State state {};
		state.rip = reinterpret_cast<uint64_t>(config_mismatch_code.data());
		state.gpr[4] = reinterpret_cast<uint64_t>(&return_address);
		return X64Interpreter(nullptr, nullptr, nullptr, nullptr, true)
		           .Run(&state, 1) == X64RunResult::Returned &&
		       state.rip == 0;
	};

	// Signal activation is diagnostic-only and process-wide. Before SIGUSR1,
	// dispatcher attempts and the thread registry remain exactly empty while
	// normal FastBlock cache/sidecar maintenance may continue. The handler only
	// requests activation; the next dispatcher boundary performs the one arm.
	EnvironmentSnapshot activation_environment {
	    "LUMEN_X64_FAST_BLOCK_TELEMETRY_WAIT_FOR_SIGNAL",
	};
	const auto set_activation_environment = [](const char* value)
	{
#if defined(_WIN32)
		_putenv_s("LUMEN_X64_FAST_BLOCK_TELEMETRY_WAIT_FOR_SIGNAL", value);
#else
		setenv("LUMEN_X64_FAST_BLOCK_TELEMETRY_WAIT_FOR_SIGNAL", value, 1);
#endif
	};
	const bool signal_activation_ok = [&]
	{
		if (!X64FastBlockTelemetrySignalActivationSupportedForTest()) return true;
		set_activation_environment("1");
		X64ResetFastBlockTelemetryForTest(1000, 1000, true);
		// Warm a negative cache entry while pending. Its sidecar must survive so
		// the first post-arm cached reject is attributable rather than dropped.
		if (!run_program(reject_code.data(), 3, 8, 2, 0) ||
		    !run_program(reject_code.data(), 3, 8, 2, 0) ||
		    !run_program(reject_code.data(), 3, 8, 2, 0))
		{
			return false;
		}
		X64RecordFastBlockTelemetryAttemptForTest(false, 0);
		X64RecordFastBlockTelemetryAttemptForTest(true, 9);
		const X64FastBlockTelemetryTestStats pre_arm =
		    X64GetFastBlockTelemetryTestStats();
		if (pre_arm.enabled || pre_arm.finalized ||
		    !pre_arm.activation_signal || pre_arm.armed ||
		    pre_arm.attempts != 0 || pre_arm.hits != 0 ||
		    pre_arm.instructions != 0 || pre_arm.rejected_attempts != 0 ||
		    pre_arm.thread_count != 0 || pre_arm.snapshots != 0 ||
		    pre_arm.dropped != 0)
		{
			return false;
		}

		if (!X64SignalFastBlockTelemetryForTest()) return false;
		const X64FastBlockTelemetryTestStats requested =
		    X64GetFastBlockTelemetryTestStats();
		if (requested.enabled || requested.armed || requested.attempts != 0)
			return false;
		std::thread arm_consumer([]
		{
			X64RecordFastBlockTelemetryAttemptForTest(true, 9);
		});
		arm_consumer.join();
		const X64FastBlockTelemetryTestStats armed =
		    X64GetFastBlockTelemetryTestStats();
		if (!armed.enabled || !armed.activation_signal || !armed.armed ||
		    armed.attempts != 1 || armed.hits != 1 || armed.instructions != 9 ||
		    armed.thread_count != 1 || armed.dropped != 0)
		{
			return false;
		}

		if (!X64SignalFastBlockTelemetryForTest() ||
		    !X64SignalFastBlockTelemetryForTest())
		{
			return false;
		}
		X64RecordFastBlockTelemetryAttemptForTest(false, 0);
		const X64FastBlockTelemetryTestStats repeated =
		    X64GetFastBlockTelemetryTestStats();
		if (!repeated.enabled || !repeated.armed || repeated.attempts != 2 ||
		    repeated.hits != 1 || repeated.instructions != 9 ||
		    repeated.thread_count != 2 || repeated.dropped != 0)
		{
			return false;
		}
		if (!run_program(reject_code.data(), 3, 8, 2, 0)) return false;
		const X64FastBlockTelemetryTestStats cached_reject =
		    X64GetFastBlockTelemetryTestStats();
		if (cached_reject.attempts <= repeated.attempts ||
		    cached_reject.rejected_attempts == 0 ||
		    cached_reject.top_reject_key != idiv_family ||
		    cached_reject.top_reject_count != cached_reject.rejected_attempts ||
		    cached_reject.dropped_sidecar != 0 || cached_reject.dropped != 0 ||
		    !X64ValidateFastBlockTelemetrySnapshotFormatForTest())
		{
			std::fprintf(
			    stderr,
			    "FastBlock telemetry pre-arm sidecar failed: attempts=%llu/%llu "
			    "rejects=%llu family=%llx/%llx count=%llu sidecar=%llu dropped=%llu\n",
			    static_cast<unsigned long long>(repeated.attempts),
			    static_cast<unsigned long long>(cached_reject.attempts),
			    static_cast<unsigned long long>(cached_reject.rejected_attempts),
			    static_cast<unsigned long long>(idiv_family),
			    static_cast<unsigned long long>(cached_reject.top_reject_key),
			    static_cast<unsigned long long>(cached_reject.top_reject_count),
			    static_cast<unsigned long long>(cached_reject.dropped_sidecar),
			    static_cast<unsigned long long>(cached_reject.dropped));
			return false;
		}

		// Ownership is checked again at every periodic/final publication. If a
		// later component replaces SIGUSR1 after arming, the due frame is emitted
		// invalid exactly once and the session cannot continue counting.
#if defined(__APPLE__) || defined(__unix__)
		X64ResetFastBlockTelemetryForTest(1, 2, true);
		if (!X64SignalFastBlockTelemetryForTest()) return false;
		X64RecordFastBlockTelemetryAttemptForTest(false, 0);
		const X64FastBlockTelemetryTestStats ownership_before =
		    X64GetFastBlockTelemetryTestStats();
		struct sigaction ignored_action {};
		struct sigaction owned_action {};
		ignored_action.sa_handler = SIG_IGN;
		if (sigemptyset(&ignored_action.sa_mask) != 0 ||
		    ::sigaction(SIGUSR1, &ignored_action, &owned_action) != 0)
		{
			return false;
		}
		X64RecordFastBlockTelemetryAttemptForTest(false, 0);
		const bool ownership_restored =
		    ::sigaction(SIGUSR1, &owned_action, nullptr) == 0;
		const X64FastBlockTelemetryTestStats ownership_after =
		    X64GetFastBlockTelemetryTestStats();
		if (!ownership_restored || !ownership_before.enabled ||
		    !ownership_before.armed || ownership_before.attempts != 1 ||
		    ownership_before.snapshots != 1 || ownership_before.dropped != 0 ||
		    ownership_after.enabled || !ownership_after.finalized ||
		    !ownership_after.armed || ownership_after.attempts != 2 ||
		    ownership_after.snapshots != 2 ||
		    ownership_after.final_snapshots != 1 ||
		    ownership_after.dropped_internal != 1 ||
		    ownership_after.dropped != 1)
		{
			return false;
		}
#endif

		// Reset clears both the pending signal and all aggregate state, returning
		// to a fresh, unarmed process-wide session.
		X64ResetFastBlockTelemetryForTest(1000, 1000, true);
		const X64FastBlockTelemetryTestStats reset =
		    X64GetFastBlockTelemetryTestStats();
		if (reset.enabled || reset.armed || !reset.activation_signal ||
		    reset.attempts != 0 || reset.hits != 0 || reset.instructions != 0 ||
		    reset.thread_count != 0 || reset.snapshots != 0 || reset.dropped != 0)
		{
			return false;
		}

		// Changing the activation contract before arming is a process config
		// mismatch: it invalidates once and can never consume later attempts.
		set_activation_environment("0");
		if (!run_config_mismatch() || !run_config_mismatch()) return false;
		X64RecordFastBlockTelemetryAttemptForTest(true, 99);
		const X64FastBlockTelemetryTestStats mismatch =
		    X64GetFastBlockTelemetryTestStats();
		return !mismatch.enabled && !mismatch.armed &&
		       mismatch.activation_signal && mismatch.attempts == 0 &&
		       mismatch.hits == 0 && mismatch.instructions == 0 &&
		       mismatch.thread_count == 0 && mismatch.snapshots == 0 &&
		       mismatch.dropped_internal == 1 && mismatch.dropped == 1;
	}();
	activation_environment.Restore();
	if (!signal_activation_ok)
	{
		std::fprintf(stderr,
		             "FastBlock telemetry SIGUSR1 activation gate failed\n");
		return false;
	}

	// Configuration is process-wide. A later Run that changes any gated field
	// disarms the session once and records an internal validity failure; neither
	// it nor later attempts can leak into the original configuration's totals.
	X64ResetFastBlockTelemetryForTest(1000, 1000);
	X64RecordFastBlockTelemetryAttemptForTest(false, 0);
	const X64FastBlockTelemetryTestStats config_before =
	    X64GetFastBlockTelemetryTestStats();
	if (!run_config_mismatch() || !run_config_mismatch()) return false;
	X64RecordFastBlockTelemetryAttemptForTest(true, 99);
	const X64FastBlockTelemetryTestStats config_after =
	    X64GetFastBlockTelemetryTestStats();
	if (config_after.enabled || config_after.finalized ||
	    config_after.attempts != config_before.attempts ||
	    config_after.hits != config_before.hits ||
	    config_after.instructions != config_before.instructions ||
	    config_after.dropped_internal != config_before.dropped_internal + 1 ||
	    config_after.dropped != config_before.dropped + 1 ||
	    config_after.snapshots != config_before.snapshots)
	{
		std::fprintf(stderr,
		             "FastBlock telemetry process config mismatch was not fail-closed\n");
		return false;
	}

	// Production is fixed at 100M attempts. This compile-only hook can only
	// lower that bound, allowing an exact periodic/final/disarm assertion.
	X64ResetFastBlockTelemetryForTest(2, 3);
	X64RecordFastBlockTelemetryAttemptForTest(false, 0);
	X64RecordFastBlockTelemetryAttemptForTest(true, 4);
	X64RecordFastBlockTelemetryAttemptForTest(false, 0);
	X64RecordFastBlockTelemetryAttemptForTest(true, 99);
	const X64FastBlockTelemetryTestStats cutoff =
	    X64GetFastBlockTelemetryTestStats();
	if (cutoff.enabled || !cutoff.finalized || cutoff.attempts != 3 ||
	    cutoff.hits != 1 || cutoff.instructions != 4 || cutoff.snapshots != 2 ||
	    cutoff.final_snapshots != 1 || cutoff.thread_count != 1 ||
	    cutoff.threads_dropped != 0 || cutoff.dropped != 0)
	{
		std::fprintf(stderr,
		             "FastBlock telemetry cutoff failed: enabled=%u finalized=%u "
		             "attempts=%llu hits=%llu instructions=%llu snapshots=%llu/%llu "
		             "dropped=%llu\n",
		             cutoff.enabled ? 1u : 0u, cutoff.finalized ? 1u : 0u,
		             static_cast<unsigned long long>(cutoff.attempts),
		             static_cast<unsigned long long>(cutoff.hits),
		             static_cast<unsigned long long>(cutoff.instructions),
		             static_cast<unsigned long long>(cutoff.snapshots),
		             static_cast<unsigned long long>(cutoff.final_snapshots),
		             static_cast<unsigned long long>(cutoff.dropped));
		return false;
	}

	// All host threads contribute to one process-wide cutoff. Each thread must
	// receive one stable bounded ordinal, while the 800th committed attempt
	// publishes exactly one final frame and disarms later records globally.
	{
		constexpr size_t thread_count = 8;
		constexpr size_t attempts_per_thread = 100;
		std::array<std::thread, thread_count> workers {};
		std::array<uint8_t, thread_count> ordinals {};
		std::atomic<size_t> ready {0};
		std::atomic<bool> start {false};
		X64ResetFastBlockTelemetryForTest(400,
		                                  thread_count * attempts_per_thread);
		for (size_t thread = 0; thread < thread_count; thread++)
		{
			workers[thread] = std::thread([&, thread]
			{
				ready.fetch_add(1, std::memory_order_release);
				while (!start.load(std::memory_order_acquire))
					std::this_thread::yield();
				for (size_t attempt = 0; attempt < attempts_per_thread; attempt++)
					X64RecordFastBlockTelemetryAttemptForTest(false, 0);
				ordinals[thread] = X64FastBlockTelemetryThreadOrdinalForTest();
			});
		}
		while (ready.load(std::memory_order_acquire) != thread_count)
			std::this_thread::yield();
		start.store(true, std::memory_order_release);
		for (auto& worker: workers) worker.join();
		auto sorted_ordinals = ordinals;
		std::sort(sorted_ordinals.begin(), sorted_ordinals.end());
		const X64FastBlockTelemetryTestStats concurrent =
		    X64GetFastBlockTelemetryTestStats();
		X64RecordFastBlockTelemetryAttemptForTest(true, 99);
		const X64FastBlockTelemetryTestStats post_final =
		    X64GetFastBlockTelemetryTestStats();
		for (size_t index = 0; index < sorted_ordinals.size(); index++)
		{
			if (sorted_ordinals[index] != index + 1)
			{
				std::fprintf(stderr,
				             "FastBlock telemetry thread ordinals are not unique\n");
				return false;
			}
		}
		if (concurrent.enabled || !concurrent.finalized ||
		    concurrent.attempts != thread_count * attempts_per_thread ||
		    concurrent.hits != 0 || concurrent.instructions != 0 ||
		    concurrent.thread_count != thread_count ||
		    concurrent.threads_dropped != 0 || concurrent.snapshots != 2 ||
		    concurrent.final_snapshots != 1 || concurrent.dropped != 0 ||
		    post_final.attempts != concurrent.attempts ||
		    post_final.hits != concurrent.hits ||
		    post_final.final_snapshots != concurrent.final_snapshots)
		{
			std::fprintf(stderr,
			             "FastBlock telemetry process-wide aggregation failed\n");
			return false;
		}
	}

	// The 65th distinct contributor is represented by one stable overflow
	// sentinel. Its data can still be accumulated, but the process is invalid
	// through both threads_dropped and dropped_thread_registry.
	{
		constexpr size_t thread_count = 65;
		std::array<std::thread, thread_count> workers {};
		std::array<uint8_t, thread_count> ordinals {};
		std::atomic<size_t> ready {0};
		std::atomic<bool> start {false};
		X64ResetFastBlockTelemetryForTest(thread_count, thread_count);
		for (size_t thread = 0; thread < thread_count; thread++)
		{
			workers[thread] = std::thread([&, thread]
			{
				ready.fetch_add(1, std::memory_order_release);
				while (!start.load(std::memory_order_acquire))
					std::this_thread::yield();
				X64RecordFastBlockRejectSampleForTest(idiv_ecx.data(),
				                                      idiv_ecx.size());
				X64RecordFastBlockTelemetryAttemptForTest(false, 0);
				ordinals[thread] = X64FastBlockTelemetryThreadOrdinalForTest();
			});
		}
		while (ready.load(std::memory_order_acquire) != thread_count)
			std::this_thread::yield();
		start.store(true, std::memory_order_release);
		for (auto& worker: workers) worker.join();
		size_t overflow_ordinals = 0;
		std::array<bool, 65> seen {};
		for (const uint8_t ordinal: ordinals)
		{
			if (ordinal == UINT8_MAX)
			{
				overflow_ordinals++;
				continue;
			}
			if (ordinal == 0 || ordinal > 64 || seen[ordinal]) return false;
			seen[ordinal] = true;
		}
		const X64FastBlockTelemetryTestStats overflow =
		    X64GetFastBlockTelemetryTestStats();
		if (overflow_ordinals != 1 || overflow.enabled || !overflow.finalized ||
		    overflow.attempts != thread_count || overflow.thread_count != 64 ||
		    overflow.threads_dropped != 1 ||
		    overflow.dropped_thread_registry != 1 || overflow.dropped != 1 ||
		    overflow.rejected_attempts != thread_count ||
		    overflow.reject_family_count != 1 ||
		    overflow.top_reject_key != idiv_family ||
		    overflow.top_reject_count != thread_count ||
		    overflow.final_snapshots != 1)
		{
			std::fprintf(stderr,
			             "FastBlock telemetry thread registry overflow failed\n");
			return false;
		}
	}

	// Fill the fixed reject table without advancing the attempt cutoff. The next
	// distinct family is a capacity drop and makes the frame invalid, while an
	// existing family remains findable and countable in the full table.
	{
		constexpr uint64_t reject_capacity = 8192;
		X64ResetFastBlockTelemetryForTest(1000, 1000);
		for (uint64_t family_key = 1; family_key <= reject_capacity; family_key++)
			X64RecordFastBlockRejectFamilyForTest(family_key);
		const X64FastBlockTelemetryTestStats capacity_full =
		    X64GetFastBlockTelemetryTestStats();
		if (capacity_full.rejected_attempts != reject_capacity ||
		    capacity_full.reject_family_count != reject_capacity ||
		    capacity_full.dropped != 0)
		{
			std::fprintf(stderr,
			             "FastBlock telemetry reject table did not fill exactly\n");
			return false;
		}
		X64RecordFastBlockRejectFamilyForTest(reject_capacity + 1);
		const X64FastBlockTelemetryTestStats capacity_dropped =
		    X64GetFastBlockTelemetryTestStats();
		if (capacity_dropped.rejected_attempts != reject_capacity + 1 ||
		    capacity_dropped.reject_family_count != reject_capacity ||
		    capacity_dropped.dropped_reject_capacity != 1 ||
		    capacity_dropped.dropped != 1 ||
		    !X64ValidateFastBlockTelemetrySnapshotFormatForTest())
		{
			std::fprintf(stderr,
			             "FastBlock telemetry reject capacity was not fail-closed\n");
			return false;
		}
		X64RecordFastBlockRejectFamilyForTest(1);
		const X64FastBlockTelemetryTestStats capacity_existing =
		    X64GetFastBlockTelemetryTestStats();
		if (capacity_existing.rejected_attempts != reject_capacity + 2 ||
		    capacity_existing.reject_family_count != reject_capacity ||
		    capacity_existing.top_reject_key != 1 ||
		    capacity_existing.top_reject_count != 2 ||
		    capacity_existing.dropped_reject_capacity != 1 ||
		    capacity_existing.dropped != 1)
		{
			std::fprintf(stderr,
			             "FastBlock telemetry full-table existing key was lost\n");
			return false;
		}
	}
	// Do not leave the compile-only test session armed for later tests that
	// intentionally toggle FastBlock configuration.
	X64ResetFastBlockTelemetryForTest(1, 1);
	X64RecordFastBlockTelemetryAttemptForTest(false, 0);
	const X64FastBlockTelemetryTestStats cleanup =
	    X64GetFastBlockTelemetryTestStats();
	if (cleanup.enabled || !cleanup.finalized || cleanup.attempts != 1 ||
	    cleanup.dropped != 0)
	{
		std::fprintf(stderr, "FastBlock telemetry test cleanup failed\n");
		return false;
	}
	return true;
}
#endif

bool TestLegacyMultiplePrefixes()
{
	constexpr std::array<uint8_t, 11> code = {
	    0x66, 0xf3, 0x0f, 0xbd, 0xe8, // LZCNT bp, ax
	    0x66, 0xf3, 0x0f, 0xb8, 0xc8, // POPCNT cx, ax
	    0xc3,
	};
	X64State state {};
	state.gpr[0] = 0x112233445566000dULL;
	state.gpr[5] = 0xaabbccddeeff1234ULL;
	state.gpr[1] = 0x8877665544332211ULL;
	if (!Run(code.data(), code.size(), &state)) return false;
	return state.gpr[5] == 0xaabbccddeeff000cULL &&
	       state.gpr[1] == 0x8877665544330003ULL;
}

bool TestGuestCancellationAfterHostCall()
{
	FastBlockTestConfiguration configuration;
	alignas(4096) static constexpr std::array<uint8_t, 4096> code = {
	    0x31, 0xc9, // XOR ecx, ecx
	    0xff, 0xd0, // CALL rax
	    0xff, 0xc1, // INC ecx (must not execute)
	    0xeb, 0xfc, // JMP back to INC ecx
	};

	auto run_cancel = [&](bool fast)
	{
		EnableFastBlocks(fast);
		for (uint32_t iteration = 0; iteration < (fast ? 4u : 1u); iteration++)
		{
			std::array<uint64_t, 2> stack {};
			X64State               state {};
			state.rip    = reinterpret_cast<uint64_t>(code.data());
			state.gpr[0] = CANCEL_HOST_CALL_TARGET;
			state.gpr[4] = reinterpret_cast<uint64_t>(stack.data() + 1);
			const uint64_t original_rsp = state.gpr[4];
			g_cancel_host_calls = 0;
			const auto result = X64Interpreter(CancelHostCall).Run(&state, 32);
			if (result != X64RunResult::StepLimit || !state.execution_cancel_requested ||
			    state.rip != reinterpret_cast<uint64_t>(code.data() + 4) ||
			    state.gpr[1] != 0 || state.gpr[4] != original_rsp ||
			    state.host_call_stack_transaction.active || g_cancel_host_calls != 1)
			{
				return false;
			}
		}
		return true;
	};

	const bool slow_ok = run_cancel(false);
	X64SetFastBlockTestTarget(reinterpret_cast<uint64_t>(code.data()));
	const bool fast_ok = run_cancel(true) && X64FastBlockTestTargetInstructionCount() != 0;
	return slow_ok && fast_ok;
}

